/* Transcribed from the three user-supplied GEMP1 EYE1 practice PDFs; 16 clusters / 120 questions per paper. */
window.MED_EYE1_PAPERS=[[{"id":"eye1-1-01","paper":"EYE1 Paper 1","module":"BCMH","title":"Collapse after an insect sting","scenario":"A 45-year-old man is stung on the neck by a wasp at a braai. Within 10 minutes he develops generalised itching, a raised\nrash, lip swelling and a hoarse voice, then collapses. He is brought to the emergency unit. He takes bisoprolol for\nhypertension and has never reacted to a sting before.\n\nObservations: BP 76/40 mmHg, HR 118/min, RR 28/min, SpO2 91% on room air, temperature 36.8 °C.\nExamination: widespread urticaria, swollen lips, audible wheeze, hoarse voice, warm flushed peripheries.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains his hypotension?","options":["Reduced myocardial contractility caused by histamine","Vasodilation and increased capillary permeability caused by mast-cell mediators","Haemorrhage from the sting site","Obstruction of venous return by laryngeal oedema"],"answer":"B","explain":"Histamine and leukotrienes cause arteriolar vasodilation and capillary leak, giving distributive shock (warm peripheries, low SVR)."},{"number":2,"type":"SBA","q":"Which finding represents the most immediate threat to life?","options":["Widespread urticaria","Hoarse voice with lip swelling","Warm flushed peripheries","History of hypertension"],"answer":"B","explain":"Hoarseness and angioedema signal impending airway obstruction. Airway comes first in ABCDE."},{"number":3,"type":"SBA","q":"Which immunological process underlies this reaction?","options":["Cross-linking of IgE bound to FcεRI on mast cells, causing degranulation","Deposition of IgG immune complexes with complement activation","Cytotoxic T-cell killing of venom-coated cells","IgG binding to cell-surface antigens with complement lysis"],"answer":"A","explain":"Type I (IgE-mediated) hypersensitivity: prior sensitisation, then allergen cross-linking and degranulation."},{"number":4,"type":"SBA","q":"What is the most appropriate first drug and route?","options":["Intravenous hydrocortisone","Intramuscular adrenaline into the anterolateral thigh","Intravenous chlorphenamine","Nebulised salbutamol"],"answer":"B","explain":"IM adrenaline is life-saving and first-line. It acts via α1 (vasoconstriction, less oedema), β1 (heart) and β2 (bronchodilation). Steroids, antihistamines and salbutamol are adjuncts and must never delay it."},{"number":5,"type":"SBA","q":"After two IM adrenaline doses his BP remains 78/42 mmHg. Which factor most likely explains the poor response,\nand which additional drug is appropriate?","options":["β-blockade from bisoprolol; give IV glucagon","ACE-inhibitor use; give icatibant","Hypokalaemia; give potassium","α-blockade; give atropine"],"answer":"A","explain":"β-blockers blunt adrenaline's β effects. Glucagon raises cAMP independently of β-receptors. Escalate to a monitored setting for an adrenaline infusion."},{"number":6,"type":"SBA","q":"Data interpretation\n\nTest                                         Result Reference\n\nSerum mast-cell tryptase, 1.5 h after onset 62 µg/L < 11.4 µg/L\n\nSerum tryptase, 24 h later                   5 µg/L < 11.4 µg/L\n\nWhich interpretation is correct?","options":["Acute mast-cell degranulation consistent with anaphylaxis, returning to baseline","Chronic systemic mastocytosis","Normal result, which excludes anaphylaxis","Eosinophilic inflammation unrelated to the sting"],"answer":"A","explain":"An acute rise that falls back to baseline supports degranulation. A normal tryptase does not exclude anaphylaxis, as diagnosis is clinical."},{"number":7,"type":"VSAQ","q":"Name the Gell and Coombs hypersensitivity type.","answer":"Type I (immediate / IgE-mediated).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which portable device should be prescribed at discharge for future stings?","answer":"Adrenaline auto-injector.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-02","paper":"EYE1 Paper 1","module":"BCMH","title":"Weight loss, oral plaques and breathlessness","scenario":"A 29-year-old woman attends a primary healthcare clinic in Soweto with 3 months of weight loss, night sweats and a dry\ncough, now with breathlessness on walking to the clinic. She has never been tested for HIV. Temperature 37.9 °C, HR\n104/min, RR 26/min. SpO2 is 94% at rest and falls to 86% after 2 minutes of walking. There are white plaques on the\ntongue and palate that scrape off, leaving a raw red base. Chest examination shows few crackles despite marked\nbreathlessness. CXR shows bilateral diffuse perihilar interstitial infiltrates.","questions":[{"number":1,"type":"SBA","q":"Which finding most strongly suggests an underlying immunodeficiency?","options":["Night sweats","Persistent oral candidiasis in an adult with no other predisposing cause","Temperature of 37.9 °C","Dry cough"],"answer":"B","explain":"Persistent oral thrush in an otherwise well adult is a WHO stage 3 feature and should prompt an HIV test."},{"number":2,"type":"SBA","q":"Which mechanism best explains her susceptibility to opportunistic infection?","options":["Loss of CD4+ T-helper cells, impairing cell-mediated immunity","Loss of neutrophils, impairing phagocytosis","Loss of B cells, impairing antibody production","Loss of complement components"],"answer":"A","explain":"HIV infects CD4+ T cells (gp120 binds CD4 plus CCR5/CXCR4), so TH1 help for macrophages and cytotoxic T cells fails, and intracellular organisms thrive."},{"number":3,"type":"SBA","q":"What is the most appropriate way to establish her HIV status?","options":["HIV DNA PCR","Rapid antibody/antigen test after consent and counselling, confirmed with a second test","CD4 count","Viral load"],"answer":"B","explain":"Adults (≥18 months) are diagnosed with serological tests. DNA PCR is for infants under 18 months because maternal IgG crosses the placenta. CD4 and viral load are for staging and monitoring."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                                Result\n\nHIV rapid tests                     Positive, confirmed\n\nCD4 count                           62 cells/µL\n\nSputum Xpert MTB/RIF                MTB not detected\n\nSerum cryptococcal antigen (CrAg) Negative\n\nSpO2                                94% rest, 86% on exertion\n\nWhich diagnosis is most likely?","options":["Pulmonary tuberculosis","Pneumocystis jirovecii pneumonia","Lobar pneumococcal pneumonia","Pulmonary Kaposi sarcoma"],"answer":"B","explain":"CD4 under 200, dry cough, exertional desaturation, bilateral perihilar infiltrates with few chest signs and a negative Xpert point to PJP."},{"number":5,"type":"SBA","q":"Which treatment is most appropriate for the suspected opportunistic infection?","options":["High-dose cotrimoxazole","Oral nystatin","Rifampicin-based therapy","Fluconazole"],"answer":"A","explain":"High-dose cotrimoxazole treats PJP (and she needs cotrimoxazole prophylaxis long term while CD4 is low)."},{"number":6,"type":"SBA","q":"Six weeks after starting ART her viral load has fallen, but she develops fever and enlarging cervical lymph nodes.\nWhat is the most likely explanation?","options":["Virological failure","Drug resistance","Immune reconstitution inflammatory syndrome","Non-adherence"],"answer":"C","explain":"Recovering immunity mounts an inflammatory response to existing antigens. A falling viral load argues against failure, resistance or non-adherence."},{"number":7,"type":"VSAQ","q":"Which antiretroviral class does dolutegravir belong to?","answer":"Integrase inhibitor (INSTI).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which single laboratory test best reflects adherence to and response to ART?","answer":"Viral load.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-03","paper":"EYE1 Paper 1","module":"BCMH","title":"Fever after travel","scenario":"A 32-year-old farm worker from the Mpumalanga lowveld visited relatives in Mozambique two weeks ago. He presents\nwith 4 days of fever, rigors, headache and vomiting and is now drowsy. Temperature 39.4 °C, HR 118/min, BP 100/60\nmmHg, RR 26/min. He is mildly jaundiced with a palpable spleen tip. A malaria rapid test (HRP-2) is positive.","questions":[{"number":1,"type":"SBA","q":"Which feature in the history most increases the pre-test probability of malaria?","options":["Working on a farm","Recent travel to a malaria-endemic area with fever","Vomiting","Headache"],"answer":"B","explain":"Fever after travel to or residence in an endemic area is malaria until proven otherwise."},{"number":2,"type":"SBA","q":"Which feature of P. falciparum best explains his drowsiness?","options":["Hypnozoite reactivation in the liver","PfEMP1-mediated sequestration of infected red cells in cerebral microvessels","Direct neuronal invasion by sporozoites","Immune-complex deposition in the glomerulus"],"answer":"B","explain":"Knobs with PfEMP1 cause cytoadherence and rosetting, obstructing the microvasculature (cerebral malaria)."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest          Result\n\nHaemoglobin 8.2 g/dL\n\nPlatelets     38 × 10⁹/L\n\nGlucose       2.4 mmol/L\n\nCreatinine    165 µmol/L\n\nThin smear    P. falciparum rings, 8% of red cells infected\n\nWhich classification is correct?","options":["Uncomplicated malaria","Severe falciparum malaria","Relapsing vivax malaria","Bacterial sepsis with incidental parasitaemia"],"answer":"B","explain":"Impaired consciousness, hypoglycaemia, renal impairment and high parasitaemia (over 2 to 5%) all define severe malaria."},{"number":4,"type":"SBA","q":"What is the safest next step?","options":["Oral artemether-lumefantrine and review in 48 hours","Wait for a thick-smear repeat before treating","IV artesunate, treat the hypoglycaemia and admit","Oral primaquine"],"answer":"C","explain":"Severe malaria needs IV artesunate and correction of glucose in hospital. Primaquine targets hypnozoites and gametocytes, not blood stages."},{"number":5,"type":"SBA","q":"Which mechanism best explains his anaemia?","options":["Marrow suppression by artemisinin","Lysis of parasitised red cells plus splenic removal of red cells","Autoimmune warm haemolysis","Iron deficiency"],"answer":"B","explain":"Schizont rupture causes intravascular haemolysis (high LDH, low haptoglobin, jaundice) and the spleen clears damaged cells."},{"number":6,"type":"SBA","q":"Which community-level measure most directly reduces transmission in endemic areas?","options":["Indoor residual spraying and insecticide-treated nets","Isolation of every febrile patient","Mass antibiotic treatment","BCG vaccination"],"answer":"A","explain":"Vector control targets the female Anopheles mosquito (the ABCD of prevention: awareness, bite prevention, chemoprophylaxis, diagnosis)."},{"number":7,"type":"VSAQ","q":"Within how many hours must this notifiable (Category 1) condition be reported?","answer":"24 hours.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-04","paper":"EYE1 Paper 1","module":"BCMH","title":"Joint pain, rash and frothy urine","scenario":"A 23-year-old woman presents with 6 weeks of painful swollen small joints of both hands, hair loss, painless mouth\nulcers and a facial rash that worsens in sunlight and spares the nasolabial folds. She has pleuritic chest pain. BP 150/95\nmmHg. Urine dipstick: blood 2+, protein 3+.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains the glomerular injury?","options":["Type III hypersensitivity: immune-complex deposition with complement activation","Type I hypersensitivity: IgE-mediated mast-cell degranulation","Type IV hypersensitivity: granuloma formation","Direct viral infection of podocytes"],"answer":"A","explain":"Loss of tolerance gives anti-nuclear antibodies and circulating immune complexes that deposit in glomeruli, skin, joints and serosa."},{"number":2,"type":"SBA","q":"Which test is the most sensitive screening test for this condition?","options":["Anti-Smith antibody","Anti-dsDNA antibody","Anti-nuclear antibody (ANA)","Rheumatoid factor"],"answer":"C","explain":"ANA is positive in virtually all patients but is not specific, so a negative ANA makes SLE very unlikely."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                          Result\n\nANA                           Positive, 1:640\n\nAnti-dsDNA                    Strongly positive\n\nC3 / C4                       Both low\n\nESR / CRP                     92 mm/h / 5 mg/L\n\nHaemoglobin / Coombs test 9.4 g/dL / positive\n\nPlatelets                     90 × 10⁹/L\n\nWhich statement is correct?","options":["Low complement with high anti-dsDNA indicates active disease with complement consumption","The normal CRP excludes lupus","A positive Coombs test indicates iron deficiency","The ESR of 92 mm/h indicates bacterial infection"],"answer":"A","explain":"Immune complexes consume C3 and C4. A high ESR with a normal CRP is the classic SLE pattern."},{"number":4,"type":"SBA","q":"Which hypersensitivity type explains her haemolytic anaemia?","options":["Type I","Type II","Type III","Type IV"],"answer":"B","explain":"Autoantibodies against red-cell surface antigens cause Type II (cytotoxic) destruction, giving a positive Coombs test."},{"number":5,"type":"SBA","q":"Which drug is recommended for all patients with this condition to reduce flares?","options":["Hydroxychloroquine, with annual eye screening","Long-term high-dose prednisone alone","Isoniazid","Rituximab for everyone"],"answer":"A","explain":"Hydroxychloroquine reduces flares. Monitor for retinopathy."},{"number":6,"type":"SBA","q":"Given her urine findings and BP, what is the most appropriate action?","options":["Reassure and review in 3 months","Treat as a urinary tract infection","NSAIDs and discharge","Urgent referral for assessment of lupus nephritis and likely renal biopsy"],"answer":"D","explain":"Haematuria, proteinuria and hypertension signal organ-threatening disease needing early specialist care. NSAIDs also risk renal injury."},{"number":7,"type":"VSAQ","q":"Name the non-infective valve vegetations seen in this condition.","answer":"Libman-Sacks.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-05","paper":"EYE1 Paper 1","module":"BCMH","title":"Painful swallowing and purple lesions","scenario":"A 36-year-old man diagnosed with HIV one month ago presents with painful swallowing for 2 weeks and weight loss.\nThere are white plaques on the tongue that scrape off. On the hard palate and both shins are purple, non-blanching\nplaques and nodules. He has not yet started ART.","questions":[{"number":1,"type":"SBA","q":"Which virus is responsible for the purple lesions?","options":["Cytomegalovirus","Human papillomavirus 16","Epstein-Barr virus","Human herpesvirus 8"],"answer":"D","explain":"HHV-8 (KSHV) causes Kaposi sarcoma, an AIDS-defining (WHO stage 4) tumour."},{"number":2,"type":"SBA","q":"Which oncogenic mechanism does this virus use?","options":["Latency-associated nuclear antigen (LANA) inactivating p53 and Rb","Insertion of a promoter next to c-myc","Reverse transcription of viral RNA into host DNA","Loss of the BRCA1 gene"],"answer":"A","explain":"LANA inactivates p53 and Rb, and viral cyclin and vGPCR drive angiogenesis and proliferation."},{"number":3,"type":"SBA","q":"Why do the lesions not blanch on pressure?","options":["They contain pus","They are due to arterial occlusion","Red cells have extravasated into slit-like vascular spaces within the tumour","They are caused by superficial fungal growth"],"answer":"C","explain":"The tumour is a spindle-cell vascular proliferation with leaky slit-like channels, so blood is outside the vessels."},{"number":4,"type":"SBA","q":"Data interpretation\nPalatal biopsy report: \"Spindle cells forming slit-like vascular spaces containing red blood cells. Immunohistochemistry:\nLANA-1 positive.\"\n\nWhat does this confirm?","options":["Bacillary angiomatosis","Pyogenic granuloma","Kaposi sarcoma","Oral hairy leukoplakia"],"answer":"C","explain":"Spindle cells, slit-like spaces and LANA-1 positivity are diagnostic of Kaposi sarcoma."},{"number":5,"type":"SBA","q":"Which is the most important first step in treating limited Kaposi sarcoma in this patient?","options":["Antiretroviral therapy","Palliative surgery only","Antifungal therapy only","Antibiotics"],"answer":"A","explain":"ART restores immunity and regresses many lesions. Chemotherapy or radiotherapy is reserved for extensive or visceral disease. Lesions may flare as IRIS."},{"number":6,"type":"SBA","q":"Fluconazole is started for oesophageal candidiasis. What is its mechanism of action?","options":["Binding ergosterol to form membrane pores","Inhibiting β-glucan synthase","Inhibiting lanosterol 14α-demethylase, reducing ergosterol synthesis","Inhibiting reverse transcriptase"],"answer":"C","explain":"Azoles inhibit CYP51 (lanosterol 14α-demethylase). Option A describes polyenes (nystatin, amphotericin B) and B describes echinocandins."},{"number":7,"type":"VSAQ","q":"What WHO clinical stage does Kaposi sarcoma or oesophageal candidiasis place a patient in?","answer":"Stage 4.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-06","paper":"EYE1 Paper 1","module":"CVS","title":"Central chest pain in a woman with diabetes","scenario":"A 63-year-old woman with type 2 diabetes and hypertension presents with 90 minutes of retrosternal heaviness\nradiating to the left arm, with sweating and nausea. It began at rest. She smokes 20 cigarettes a day. BP 138/84 mmHg,\nHR 94/min, RR 20/min, SpO2 97% on room air. Lungs are clear. ECG: ST-segment depression and T-wave inversion in V4\nto V6, with no ST elevation.","questions":[{"number":1,"type":"SBA","q":"Which pathological process most likely underlies her presentation?","options":["Stable atherosclerotic narrowing with no change in the plaque","Plaque rupture or erosion with a partially occlusive thrombus","Coronary embolism from the left atrium","Aortic dissection involving the coronary ostia"],"answer":"B","explain":"Acute coronary syndrome results from a disrupted vulnerable plaque (thin cap, large lipid core) with platelet- fibrin thrombus. Stable angina is a fixed narrowing without thrombosis."},{"number":2,"type":"SBA","q":"What is the most appropriate interpretation of the ECG?","options":["Normal variant","Pericarditis","Acute coronary syndrome without ST elevation","Left bundle branch block"],"answer":"C","explain":"ST depression and T inversion in the lateral leads with ischaemic pain is ACS without ST elevation (unstable angina or NSTEMI, separated by troponin)."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTime from arrival High-sensitivity troponin I Reference (99th percentile)\n\n0h                 12 ng/L                     < 14 ng/L\n\n3h                 340 ng/L                    < 14 ng/L\n\nWhich interpretation is correct?","options":["Normal result, so myocardial injury is excluded","A significant rise above the 99th percentile in keeping with myocardial necrosis (NSTEMI)","Chronic kidney disease only","Skeletal muscle injury"],"answer":"B","explain":"MI requires a rise and/or fall of troponin with at least one value above the 99th percentile plus evidence of ischaemia. A single early normal value does not exclude MI, hence serial testing."},{"number":4,"type":"SBA","q":"Which drug should be given immediately?","options":["Aspirin","Intravenous morphine for all patients","A calcium-channel blocker","High-flow oxygen for all patients"],"answer":"A","explain":"Aspirin (an antiplatelet) is given early in ACS. Oxygen is only for SpO2 below 90%, and morphine is used only if pain persists."},{"number":5,"type":"SBA","q":"Why is routine high-flow oxygen not recommended when SpO2 is normal?","options":["It causes bradycardia in all patients","It has no effect on myocardium","It may increase coronary vasoconstriction and has no proven benefit when saturation is adequate","It reduces troponin release"],"answer":"C","explain":"Hyperoxia can cause coronary vasoconstriction and gives no benefit in normoxic patients."},{"number":6,"type":"SBA","q":"On day 4 she develops a new loud pansystolic murmur at the apex with acute pulmonary oedema. What is the most\nlikely cause?","options":["Reinfarction","Dressler syndrome","Aortic dissection","Papillary muscle rupture causing acute mitral regurgitation"],"answer":"D","explain":"Days 3 to 7 is when macrophage-mediated softening of necrotic myocardium weakens structures, including the papillary muscle. Dressler syndrome is pericarditis weeks later with a rub and fever."},{"number":7,"type":"VSAQ","q":"What type of necrosis occurs in a myocardial infarct?","answer":"Coagulative necrosis.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which drug class is started for secondary prevention to lower LDL cholesterol and stabilise plaques?","answer":"Statin.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-07","paper":"EYE1 Paper 1","module":"CVS","title":"Breathlessness and swollen legs","scenario":"A 58-year-old man from Soweto with long-standing untreated hypertension presents with 3 weeks of progressive\nbreathlessness on exertion, needing three pillows to sleep, waking at night gasping, and swollen ankles. BP 168/102\nmmHg, HR 102/min, RR 28/min, SpO2 91% on room air. JVP is raised, there are bibasal crackles, a third heart sound, a\ndisplaced apex beat and pitting oedema to the knees.","questions":[{"number":1,"type":"SBA","q":"Which process best explains the development of his cardiac condition?","options":["Chronic pressure overload causing left ventricular hypertrophy, then dilatation and failure","Acute rheumatic valve scarring","Congenital septal defect","Pericardial constriction from tuberculosis"],"answer":"A","explain":"Hypertensive heart disease is the commonest cause of heart failure in SA. Pressure overload gives concentric LVH (diastolic dysfunction), then dilatation and systolic failure."},{"number":2,"type":"SBA","q":"Which mechanism best explains his orthopnoea and bibasal crackles?","options":["Pleural inflammation","Raised pulmonary capillary hydrostatic pressure with transudation of fluid into alveoli","Bronchospasm","Alveolar consolidation by neutrophils"],"answer":"B","explain":"Raised left atrial and pulmonary venous pressure forces fluid into interstitium and alveoli. Lying flat increases venous return and worsens it."},{"number":3,"type":"SBA","q":"The third heart sound is best explained by which of the following?","options":["Atrial contraction against a stiff ventricle","Opening of a stenotic mitral valve","Rapid early diastolic filling of a dilated, volume-loaded ventricle","Pericardial friction"],"answer":"C","explain":"An S3 indicates volume overload with rapid filling in early diastole. An S4 reflects atrial contraction into a stiff ventricle."},{"number":4,"type":"SBA","q":"Data interpretation\n\nInvestigation     Result\n\nEchocardiogram LVEF 28%, dilated LV, global hypokinesia\n\nChest X-ray       Cardiomegaly, upper-lobe venous diversion, Kerley B lines, small bilateral effusions\n\nNT-proBNP         4 500 pg/mL (raised)\n\nWhat is the best interpretation?","options":["Heart failure with reduced ejection fraction and pulmonary congestion","Heart failure with preserved ejection fraction","Pulmonary embolism","Interstitial lung disease"],"answer":"A","explain":"EF at or below 40% defines HFrEF. Kerley B lines, venous diversion and effusions show congestion."},{"number":5,"type":"SBA","q":"Which drug class gives the fastest relief of his congestion?","options":["Loop diuretic","β-blocker started at full dose","Calcium-channel blocker (verapamil)","Aspirin"],"answer":"A","explain":"Loop diuretics reduce preload and oedema. Starting a β-blocker in decompensated failure, or verapamil in HFrEF, can worsen the situation."},{"number":6,"type":"SBA","q":"Which therapy improves long-term survival in HFrEF?","options":["Loop diuretics alone","ACE inhibitor (with a β-blocker introduced when stable)","Digoxin alone","Nitrates alone"],"answer":"B","explain":"ACE inhibitors and β-blockers (plus MRAs) reduce mortality. Diuretics relieve symptoms but do not improve survival."},{"number":7,"type":"VSAQ","q":"What are the haemosiderin-laden macrophages found in the lungs in chronic left heart failure called?","answer":"Heart failure cells.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What term describes the heart's ability to increase stroke volume when end-diastolic stretch increases?","answer":"Frank-Starling mechanism.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-08","paper":"EYE1 Paper 1","module":"CVS","title":"Palpitations in a young woman","scenario":"A 29-year-old woman from rural Eastern Cape presents with 2 months of palpitations and breathlessness on exertion. At\nage 9 she had a febrile illness with migrating joint pains, which was diagnosed as rheumatic fever. She never received\nregular injections afterwards. Pulse is irregularly irregular at 130/min, BP 110/70 mmHg. Examination: loud S1, an\nopening snap and a low-pitched mid-diastolic rumbling murmur at the apex. ECG shows an irregularly irregular rhythm\nwith no P waves.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains how streptococcal infection damaged her valve?","options":["Direct bacterial invasion of the valve","Toxin-mediated necrosis of valve leaflets","Molecular mimicry: antibodies and T cells against M protein cross-react with cardiac antigens","Type I hypersensitivity to streptococcal antigens"],"answer":"C","explain":"Group A streptococcal M protein resembles cardiac proteins, so the immune response attacks the heart. Aschoff bodies and valve scarring follow repeated attacks."},{"number":2,"type":"SBA","q":"Which valve lesion is most likely?","options":["Aortic regurgitation","Mitral stenosis","Tricuspid regurgitation","Pulmonary stenosis"],"answer":"B","explain":"A loud S1, opening snap and mid-diastolic rumble are the signs of mitral stenosis. The mitral valve is most commonly affected in RHD."},{"number":3,"type":"SBA","q":"Which mechanism best explains her atrial fibrillation?","options":["Left atrial pressure overload and dilatation due to obstruction at the mitral valve","Left ventricular hypertrophy","Hypokalaemia","Sinus node ischaemia"],"answer":"A","explain":"Obstructed left atrial emptying dilates the atrium and disrupts conduction, causing AF."},{"number":4,"type":"SBA","q":"Why is she at high risk of stroke?","options":["Hypertension","Rupture of a berry aneurysm","Stasis of blood in a dilated left atrium leading to thrombus formation and embolism","Carotid atherosclerosis"],"answer":"C","explain":"Stasis in a fibrillating, dilated atrium favours thrombus. This is cardio-embolic stroke."},{"number":5,"type":"SBA","q":"Which anticoagulant is appropriate for her?","options":["Aspirin alone","Warfarin (INR target 2 to 3)","A DOAC, since it is easier to use","No anticoagulation, since she is young"],"answer":"B","explain":"AF with rheumatic mitral stenosis needs a vitamin K antagonist. DOACs are not recommended in this setting."},{"number":6,"type":"SBA","q":"Data interpretation\n\nDate              INR Target\n\nDay 7 on warfarin 1.4 2.0 to 3.0\n\nWhat does this show?","options":["Therapeutic anticoagulation","Over-anticoagulation with bleeding risk","Sub-therapeutic anticoagulation with persisting stroke risk","Warfarin is not absorbed in rheumatic disease"],"answer":"C","explain":"An INR of 1.4 is below 2 to 3. Check adherence, diet and interactions, adjust the dose and monitor."},{"number":7,"type":"VSAQ","q":"Which injectable antibiotic is used for secondary prophylaxis of rheumatic fever?","answer":"Benzathine penicillin.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-09","paper":"EYE1 Paper 1","module":"CVS","title":"Sudden weakness and speech difficulty","scenario":"A 67-year-old woman with long-standing untreated hypertension is found by her husband 1 hour ago with a right facial\ndroop and right arm weakness. She cannot speak, although she follows commands. Pulse irregularly irregular at 96/min,\nBP 190/105 mmHg, glucose 6.2 mmol/L. Onset was sudden while she was watching television. The nearest hospital with\nCT is 3 hours away.","questions":[{"number":1,"type":"SBA","q":"Which vascular territory is most likely involved?","options":["Right middle cerebral artery","Left middle cerebral artery","Basilar artery","Right posterior cerebral artery"],"answer":"B","explain":"Right face and arm weakness with aphasia suggests the left (dominant) MCA territory."},{"number":2,"type":"SBA","q":"Which mechanism is most likely given her pulse?","options":["Haemorrhage from a berry aneurysm","Small-vessel lacunar infarct only","Hypoglycaemia","Cardio-embolic occlusion from atrial fibrillation"],"answer":"D","explain":"Irregularly irregular pulse suggests AF, giving left atrial thrombus and embolus to the cerebral circulation."},{"number":3,"type":"SBA","q":"What is the most important investigation before any thrombolysis decision?","options":["Lumbar puncture","Non-contrast CT brain","Carotid ultrasound","Fasting lipogram"],"answer":"B","explain":"A CT excludes haemorrhage, as thrombolysis in a bleed would be dangerous."},{"number":4,"type":"SBA","q":"Data interpretation\nNon-contrast CT brain: \"No haemorrhage. Loss of grey-white differentiation and insular ribbon sign in the left MCA\nterritory.\"\n\nWhat is the correct interpretation?","options":["Intracerebral haemorrhage","Early ischaemic infarct, so thrombolysis can be considered if within the time window and no contraindications","Normal CT, so stroke is excluded","Brain tumour"],"answer":"B","explain":"Early ischaemic signs on CT with no bleed in a patient within 4.5 hours may allow alteplase."},{"number":5,"type":"SBA","q":"What is the correct approach to her BP of 190/105 mmHg?","options":["Lower it rapidly to normal with IV drugs","Avoid aggressive lowering unless she is receiving thrombolysis or has hypertensive emergency, because the penumbra depends on collateral perfusion","Ignore it completely","Give a loop diuretic"],"answer":"B","explain":"Permissive hypertension protects the ischaemic penumbra. BP is lowered (to below 185/110) only before thrombolysis."},{"number":6,"type":"SBA","q":"CT and thrombolysis are not available locally. What is the most appropriate action?","options":["Send her home and review in 1 week","Give aspirin and wait 24 hours","Arrange urgent transfer to a stroke-capable facility while stabilising ABC and glucose","Start warfarin immediately"],"answer":"C","explain":"Time is brain. Rural inequity of access to CT is a key health-system issue, so early referral and transport matter."},{"number":7,"type":"VSAQ","q":"What type of necrosis occurs in a cerebral infarct?","answer":"Liquefactive necrosis.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-10","paper":"EYE1 Paper 1","module":"CVS","title":"Fever, confusion and low blood pressure","scenario":"A 52-year-old woman with type 2 diabetes is brought to the emergency unit with 2 days of dysuria, fever and vomiting,\nand is now confused. Temperature 39.2 °C, HR 126/min, BP 82/44 mmHg, RR 30/min, SpO2 94% on room air. Capillary\nrefill is 4 seconds and her peripheries are cool and mottled. She has passed 10 mL of urine in 4 hours. There is right flank\ntenderness.","questions":[{"number":1,"type":"SBA","q":"Which feature best distinguishes sepsis from a simple urinary tract infection?","options":["Fever","Dysuria","Flank tenderness","New confusion, hypotension and oliguria showing organ dysfunction"],"answer":"D","explain":"Sepsis is suspected infection with life-threatening organ dysfunction caused by a dysregulated host response."},{"number":2,"type":"SBA","q":"Which mechanism best explains her hypotension?","options":["Cytokine-mediated (TNF-α, IL-1, IL-6) vasodilation and capillary leak with relative hypovolaemia","Primary pump failure","Obstruction of the pulmonary arteries","Acute blood loss"],"answer":"A","explain":"PAMPs and DAMPs activate macrophages, releasing cytokines and nitric oxide that cause vasodilation and leaky capillaries (distributive shock)."},{"number":3,"type":"SBA","q":"Which type of shock does this best represent?","options":["Cardiogenic","Obstructive","Distributive (septic)","Neurogenic"],"answer":"C","explain":"Septic shock is distributive. Peripheries may be cool late in the course once cardiac output falls."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest        Result\n\nLactate     5.2 mmol/L (normal < 2)\n\nCreatinine 210 µmol/L (baseline 70)\n\nPlatelets   85 × 10⁹/L\n\nGlucose     14 mmol/L\n\nWhat do these results indicate?","options":["Isolated hyperglycaemia","Tissue hypoperfusion with acute kidney injury and a coagulation abnormality, in keeping with sepsis with organ dysfunction","Dehydration only","Diabetic ketoacidosis"],"answer":"B","explain":"A high lactate shows anaerobic metabolism from hypoperfusion. Rising creatinine and low platelets show renal and haematological organ dysfunction."},{"number":5,"type":"SBA","q":"Which action is the priority in the first hour?","options":["Await urine culture results before treating","Give oral antibiotics and review in 24 hours","Obtain blood cultures, then give broad-spectrum IV antibiotics and IV fluids immediately","Give only antipyretics"],"answer":"C","explain":"Cultures before antibiotics where this causes no delay, but treatment must not be delayed. The first hour matters."},{"number":6,"type":"SBA","q":"Despite 30 mL/kg of IV crystalloid her MAP remains below 65 mmHg. What is the most appropriate next step?","options":["Give more fluid indefinitely","Start a vasopressor such as noradrenaline and escalate to ICU or senior care","Discharge once the temperature settles","Give beta-blockers to slow the heart"],"answer":"B","explain":"Persistent hypotension after fluids defines septic shock and needs vasopressors and escalation."},{"number":7,"type":"VSAQ","q":"Which Gram-negative organism most commonly causes this type of urinary sepsis?","answer":"E. coli (Escherichia coli).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which renal pathology explains the rising creatinine?","answer":"Acute tubular necrosis.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-11","paper":"EYE1 Paper 1","module":"CVS","title":"The blue baby","scenario":"A 4-month-old boy is brought to a rural KZN clinic. His mother says he turns blue when crying or feeding and once\nbecame limp during an episode. He is feeding poorly and has gained little weight. SpO2 is 82% on room air. There is a\nharsh ejection systolic murmur at the left upper sternal edge, a single second heart sound and a right ventricular heave.\nChest X-ray shows a boot-shaped heart with reduced pulmonary vascular markings.","questions":[{"number":1,"type":"SBA","q":"Which congenital heart defect is most likely?","options":["Atrial septal defect","Patent ductus arteriosus","Coarctation of the aorta","Tetralogy of Fallot"],"answer":"D","explain":"Cyanosis with an RVOT murmur, a single S2 and a boot-shaped heart with oligaemic lungs is classic Tetralogy of Fallot."},{"number":2,"type":"SBA","q":"Which set lists the four components of this condition?","options":["VSD, pulmonary stenosis (RVOT obstruction), overriding aorta, right ventricular hypertrophy","ASD, mitral stenosis, aortic stenosis, left ventricular hypertrophy","VSD, patent ductus, coarctation, left ventricular hypertrophy","Transposition, VSD, ASD, pulmonary atresia"],"answer":"A","explain":"The four components of Tetralogy of Fallot are a VSD, RVOT obstruction, an overriding aorta and RVH."},{"number":3,"type":"SBA","q":"Which mechanism causes his cyanosis?","options":["Left-to-right shunt through the VSD","Right-to-left shunting of deoxygenated blood across the VSD because of RVOT obstruction","Pulmonary oedema","Bronchospasm"],"answer":"B","explain":"Obstruction to pulmonary outflow raises right ventricular pressure and deoxygenated blood bypasses the lungs."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                                    Result\n\nSpO2 on room air                        82%\n\nSpO2 after 10 minutes of 100% oxygen 84%\n\nWhat does this response suggest?","options":["Primary lung disease","Anaemia","Normal result","A fixed intracardiac right-to-left shunt rather than lung disease"],"answer":"D","explain":"In lung disease oxygen raises saturation. Failure to improve (hyperoxia test) points to a cardiac shunt."},{"number":5,"type":"SBA","q":"During a hypercyanotic spell, which first-aid position helps?","options":["Lying flat with legs lowered","Knee-chest position (or squatting in older children)","Prone, face down","Sitting upright with legs dangling"],"answer":"B","explain":"Flexing the legs increases systemic vascular resistance, reducing right-to-left shunt, and returns more blood to the lungs."},{"number":6,"type":"SBA","q":"Which investigation confirms the diagnosis?","options":["Electrocardiogram","Echocardiography","Pulse oximetry alone","Chest X-ray alone"],"answer":"B","explain":"Echocardiography is diagnostic and defines anatomy for surgical planning. The ECG and CXR are supportive only."},{"number":7,"type":"VSAQ","q":"Which simple newborn screening test can detect critical congenital heart disease before discharge?","answer":"Pulse oximetry.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-12","paper":"EYE1 Paper 1","module":"RESP","title":"Wheeze and breathlessness in a teenager","scenario":"A 15-year-old girl with eczema and allergic rhinitis, and a history of night-time cough, arrives at the emergency unit\nunable to complete sentences. She has wheezed since the morning and her inhaler is not helping. RR 34/min, HR\n130/min, SpO2 89% on room air, PEF 30% of predicted. Chest examination shows widespread wheeze and she appears\nexhausted.","questions":[{"number":1,"type":"SBA","q":"Which underlying process best explains her condition?","options":["Chronic airway inflammation (TH2, eosinophils, IgE) with reversible bronchoconstriction","Irreversible destruction of alveolar walls","Infection by Mycobacterium tuberculosis","Pulmonary vascular obstruction"],"answer":"A","explain":"Asthma is chronic eosinophilic airway inflammation with hyperresponsiveness, mucus plugging and reversible airflow limitation."},{"number":2,"type":"SBA","q":"Which finding would be most ominous?","options":["Audible wheeze","Tachycardia","A \"quiet chest\" with drowsiness or exhaustion","Cough"],"answer":"C","explain":"A silent chest means very little air is moving. Together with exhaustion, it signals impending respiratory failure."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest            Result\n\nPEF             30% of predicted\n\nSpO2            89% on room air\n\nArterial PaCO2 6.1 kPa (normal 4.7 to 6.0)\n\nWhat does the PaCO2 indicate?","options":["Reassuring, since it is close to normal","A normal or rising PaCO2 in a severe attack suggests fatigue and impending respiratory failure","Metabolic acidosis","Hypoventilation from opioids"],"answer":"B","explain":"In a severe attack patients hyperventilate and PaCO2 should be low. A normal or high value is a danger sign."},{"number":4,"type":"SBA","q":"What is the most appropriate immediate management?","options":["Antibiotics and discharge","Oxygen, nebulised salbutamol with ipratropium, and systemic corticosteroid, with senior review","Long-acting β2-agonist alone","Antihistamines"],"answer":"B","explain":"Standard acute care is oxygen, repeated SABA with ipratropium, and early systemic steroid."},{"number":5,"type":"SBA","q":"Why should a long-acting β2-agonist never be used without an inhaled corticosteroid?","options":["It causes hypertension","It treats inflammation too strongly","It has no bronchodilator effect","It masks symptoms while inflammation goes untreated and increases the risk of death"],"answer":"D","explain":"LABA alone relieves bronchospasm but leaves airway inflammation uncontrolled. The ICS is the controller cornerstone (ICS-formoterol as MART)."},{"number":6,"type":"SBA","q":"Which therapy is most appropriate for her allergic rhinitis, a Type I hypersensitivity condition?","options":["Oral antibiotics","Intranasal corticosteroid","Long-term decongestant nasal spray","Intravenous adrenaline"],"answer":"B","explain":"Intranasal steroids are the most effective treatment for allergic rhinitis. Decongestants over 5 to 7 days cause rhinitis medicamentosa. Controlling rhinitis also helps asthma (the united airway)."},{"number":7,"type":"VSAQ","q":"Which lung function test confirms reversible airflow obstruction?","answer":"Spirometry (with bronchodilator reversibility).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-13","paper":"EYE1 Paper 1","module":"RESP","title":"Chronic smoker with worsening breathlessness","scenario":"A 66-year-old retired gold miner, with a 45 pack-year smoking history, presents with 3 days of worsening breathlessness,\nincreased wheeze and green sputum. He has a chronic morning cough. RR 28/min, HR 110/min, SpO2 84% on room air.\nHe has a barrel chest, breathes through pursed lips and has a prolonged expiratory phase. Arterial blood gas on room\nair: pH 7.31, PaCO2 8.2 kPa, PaO2 6.9 kPa, HCO3 34 mmol/L.","questions":[{"number":1,"type":"SBA","q":"Which process explains the chronic airflow limitation in this patient?","options":["Reversible bronchospasm only","Alveolar wall destruction (emphysema) and chronic bronchial inflammation with mucus hypersecretion","Granulomatous inflammation","Pulmonary vascular thrombosis"],"answer":"B","explain":"Smoking causes a protease-antiprotease imbalance (emphysema) and chronic bronchitis, giving largely irreversible obstruction."},{"number":2,"type":"SBA","q":"Why does he breathe through pursed lips?","options":["To increase airway pressure and prevent early airway collapse in expiration","To lower CO2","To reduce airway resistance by cooling air","To open the alveoli"],"answer":"A","explain":"Pursed-lip breathing creates back-pressure that keeps small airways open during expiration."},{"number":3,"type":"SBA","q":"Data interpretation\n\nParameter Result       Normal\n\npH         7.31        7.35 to 7.45\n\nPaCO2      8.2 kPa     4.7 to 6.0\n\nPaO2       6.9 kPa     10 to 13\n\nHCO3       34 mmol/L 22 to 26\n\nWhat is the correct interpretation?","options":["Metabolic acidosis","Acute respiratory alkalosis","Type 2 respiratory failure with respiratory acidosis and partial metabolic compensation (acute-on-chronic)","Normal gas exchange"],"answer":"C","explain":"High PaCO2 with low pH is respiratory acidosis. The raised bicarbonate shows chronic renal compensation, so this is acute-on-chronic."},{"number":4,"type":"SBA","q":"Which approach to oxygen therapy is correct?","options":["Withhold all oxygen because of his CO2 retention","Titrated controlled oxygen (e.g. Venturi mask) aiming for SpO2 88 to 92%","High-flow 100% oxygen by non-rebreather mask","Oxygen only if SpO2 is above 98%"],"answer":"B","explain":"Hypoxaemia kills first, so give oxygen, but avoid over-oxygenation, which worsens CO2 retention in COPD."},{"number":5,"type":"SBA","q":"Which treatment is most appropriate for this exacerbation?","options":["Nebulised bronchodilators (SABA and ipratropium), oral prednisone for 5 days, and antibiotics for purulent sputum","Antihistamines alone","Long-term home oxygen only","Intravenous adrenaline"],"answer":"A","explain":"This is the standard exacerbation package. Consider NIV if acidosis persists."},{"number":6,"type":"SBA","q":"Which single intervention most reduces long-term mortality in COPD?","options":["Mucolytics","Regular SABA","Smoking cessation","Chest physiotherapy"],"answer":"C","explain":"Smoking cessation is the only intervention (with long-term oxygen for hypoxaemic patients) that slows decline and reduces mortality."},{"number":7,"type":"VSAQ","q":"Which spirometry ratio is reduced (below 0.7 after bronchodilator) in COPD?","answer":"FEV1/FVC ratio.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-14","paper":"EYE1 Paper 1","module":"RESP","title":"Fever, cough and breathlessness in an older man","scenario":"A 74-year-old man from a care home is brought in with 3 days of productive cough with rusty sputum, right-sided\npleuritic chest pain and fever. He is new-onset confused. Temperature 39 °C, HR 112/min, BP 98/58 mmHg, RR 32/min,\nSpO2 88% on room air. There is dullness to percussion, increased vocal fremitus and bronchial breathing at the right\nbase. CXR shows right lower lobe consolidation with air bronchograms. Urea is 9.8 mmol/L.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely cause?","options":["Mycobacterium tuberculosis","Pneumocystis jirovecii","Streptococcus pneumoniae","Respiratory syncytial virus"],"answer":"C","explain":"S. pneumoniae is the commonest cause of lobar community-acquired pneumonia, with rusty sputum and pleuritic pain."},{"number":2,"type":"SBA","q":"Which pathological process produces the consolidation?","options":["Granuloma formation with caseation","Alveolar spaces filled with a neutrophil-rich inflammatory exudate","Diffuse alveolar wall fibrosis","Air trapping from airway collapse"],"answer":"B","explain":"Alveoli fill with fibrin, neutrophils and fluid (red then grey hepatisation), so the lobe becomes solid."},{"number":3,"type":"SBA","q":"Which examination finding is best explained by consolidation?","options":["Hyper-resonant percussion note","Absent breath sounds with tracheal deviation","Reduced vocal fremitus","Increased vocal fremitus with bronchial breathing"],"answer":"D","explain":"Solid lung conducts sound better than air-filled lung."},{"number":4,"type":"SBA","q":"Data interpretation: CURB-65\n\nVariable                           Patient\n\nConfusion (new)                    Yes\n\nUrea > 7 mmol/L                    9.8 (yes)\n\nRespiratory rate ≥ 30/min          32 (yes)\n\nBP: systolic < 90 or diastolic ≤ 60 98/58 (diastolic ≤ 60, yes)\n\nAge ≥ 65                           74 (yes)\n\nWhat is his CURB-65 score and what does it mean?","options":["1: manage as an outpatient","2: short hospital stay","5: certain death","5: severe pneumonia, admit and consider ICU"],"answer":"D","explain":"Confusion, urea, RR, BP (diastolic 58 is 60 or below) and age all score, giving 5. A score of 3 or more is severe pneumonia, needing hospital admission with senior or ICU review."},{"number":5,"type":"SBA","q":"Which mechanism best explains his hypoxaemia?","options":["Hypoventilation from respiratory depression","Reduced haemoglobin","Ventilation-perfusion mismatch with blood passing through consolidated, unventilated alveoli (shunt)","Carbon monoxide poisoning"],"answer":"C","explain":"Perfused but unventilated alveoli act as a right-to-left shunt, so supplemental oxygen only partly corrects it."},{"number":6,"type":"SBA","q":"What is the safest next step?","options":["Oral antibiotics and send him back to the care home","Chest physiotherapy only","Await sputum culture before treating","Oxygen, IV antibiotics, IV fluids and early escalation to a senior doctor"],"answer":"D","explain":"Severe CAP with hypoxaemia and confusion is a medical emergency."},{"number":7,"type":"VSAQ","q":"What is pus in the pleural space called?","answer":"Empyema.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which vaccine helps prevent invasive disease from this organism?","answer":"Pneumococcal conjugate vaccine (PCV).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-15","paper":"EYE1 Paper 1","module":"RESP","title":"Chronic cough, haemoptysis and weight loss","scenario":"A 38-year-old woman from Alexandra township presents with 6 weeks of cough with blood-streaked sputum, fever,\nnight sweats and a 9 kg weight loss. Two years ago she was treated for tuberculosis but stopped her tablets after 3\nmonths because she felt better. HR 100/min, temperature 37.9 °C, SpO2 94% on room air. There are crackles in the right\nupper zone. CXR shows a right upper lobe cavity. A rapid HIV test is positive.","questions":[{"number":1,"type":"SBA","q":"Which process best explains the cavity on her X-ray?","options":["Neutrophilic abscess due to Staphylococcus aureus","Pulmonary infarction","Caseous necrosis within granulomas that liquefies and erodes into an airway","Emphysematous bulla"],"answer":"C","explain":"Caseating granulomas liquefy, discharge into the bronchus and leave a cavity, which also explains haemoptysis and infectiousness."},{"number":2,"type":"SBA","q":"Which feature in her history most increases the likelihood of drug-resistant disease?","options":["HIV positivity","Weight loss","Previous incomplete treatment","Living in a township"],"answer":"C","explain":"Incomplete therapy selects resistant mutants."},{"number":3,"type":"SBA","q":"Which is the most appropriate initial test on a sputum sample?","options":["Chest CT","Tuberculin skin test","Sputum Gram stain","Xpert MTB/RIF"],"answer":"D","explain":"Xpert detects M. tuberculosis DNA and rifampicin resistance within hours. A skin test cannot distinguish latent from active disease."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                    Result\n\nSputum Xpert MTB/RIF MTB detected, rifampicin resistance detected\n\nHIV                     Positive\n\nCD4 count               210 cells/µL\n\nWhat is the most appropriate interpretation?","options":["Standard first-line drug-sensitive therapy is sufficient","Latent infection only","Rifampicin-resistant TB requiring a drug-resistant TB regimen (e.g. BPaLM) and specialist input","Non-tuberculous mycobacterial infection"],"answer":"C","explain":"Rifampicin resistance means standard RHZE will fail. Rifampicin-resistant TB is treated with the BPaLM regimen under specialist guidance."},{"number":5,"type":"SBA","q":"Which measure best reduces TB transmission within the clinic?","options":["Treating every waiting patient with isoniazid","Triage coughing patients, ventilate rooms and provide N95 respirators for staff","Providing surgical masks to staff only","Isolating only patients with HIV"],"answer":"B","explain":"TB spreads by airborne droplet nuclei, so ventilation, cough triage and N95s are key infection-prevention controls."},{"number":6,"type":"SBA","q":"Which public-health action is most appropriate?","options":["Notify the case and trace and screen household contacts","Treat the whole township empirically","Report only if she consents","Wait for contacts to develop symptoms"],"answer":"A","explain":"TB is a notifiable condition, and contact tracing is central to control. Contacts are assessed for active TB and offered preventive therapy if eligible."},{"number":7,"type":"VSAQ","q":"Which stain identifies acid-fast bacilli on sputum microscopy?","answer":"Ziehl-Neelsen.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which T-cell cytokine activates macrophages to control M. tuberculosis?","answer":"Interferon-gamma.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"},{"id":"eye1-1-16","paper":"EYE1 Paper 1","module":"RESP","title":"Sudden pleuritic chest pain and breathlessness","scenario":"A 31-year-old woman who smokes and takes the combined oral contraceptive pill returns from a 10-hour flight with\nsudden-onset breathlessness and right-sided pleuritic chest pain. Her left calf is swollen and tender. HR 112/min, RR\n26/min, BP 118/72 mmHg, SpO2 91% on room air. The chest is clear.","questions":[{"number":1,"type":"SBA","q":"Which Virchow triad components are present?","options":["Endothelial injury only","Venous stasis and hypercoagulability","Hyperviscosity only","None"],"answer":"B","explain":"The long flight causes stasis, and oestrogen from the pill (and smoking) causes hypercoagulability."},{"number":2,"type":"SBA","q":"Which mechanism best explains her hypoxaemia?","options":["Pulmonary oedema","Alveolar consolidation","Ventilation-perfusion mismatch: ventilated alveoli that are not perfused (dead space) with redistribution of flow","Airway obstruction"],"answer":"C","explain":"Thrombus blocks pulmonary arterial flow, so ventilated alveoli get no blood. Flow is diverted to other areas, causing V/Q mismatch."},{"number":3,"type":"SBA","q":"Her Wells score indicates a high probability of PE. What is the most appropriate approach to confirmation?","options":["Perform a D-dimer to exclude PE","Proceed directly to CT pulmonary angiography","Chest X-ray alone","Wait and repeat examination tomorrow"],"answer":"B","explain":"D-dimer is used to rule out PE only when pre-test probability is low or unlikely. High probability goes straight to CTPA."},{"number":4,"type":"SBA","q":"Data interpretation\n\nArterial blood gas Result      Normal\n\npH                 7.48        7.35 to 7.45\n\nPaCO2              3.6 kPa     4.7 to 6.0\n\nPaO2               7.9 kPa     10 to 13\n\nHCO3               24 mmol/L 22 to 26\n\nWhat is the correct interpretation?","options":["Metabolic acidosis","Respiratory acidosis","Respiratory alkalosis with hypoxaemia","Normal"],"answer":"C","explain":"Hypoxaemia drives hyperventilation, which blows off CO2 and raises pH."},{"number":5,"type":"SBA","q":"What should be started while awaiting imaging, assuming no contraindication?","options":["Therapeutic anticoagulation (e.g. LMWH)","Antibiotics","Bronchodilators","Diuretics"],"answer":"A","explain":"When suspicion is high, start anticoagulation before the scan."},{"number":6,"type":"SBA","q":"Which new finding would suggest a high-risk (massive) PE needing urgent escalation?","options":["Cough","Sustained hypotension or shock","Pleuritic pain","Calf swelling"],"answer":"B","explain":"Hypotension signals right ventricular failure and obstructive shock. Escalate for reperfusion (thrombolysis) and ICU care."},{"number":7,"type":"VSAQ","q":"Which blood test has high sensitivity but low specificity and is used to rule out PE when probability is low?","answer":"D-dimer.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What type of pulmonary infarct may follow a PE?","answer":"Haemorrhagic (red) infarct.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 1 (educational practice, not an official Wits exam)"}],[{"id":"eye1-2-01","paper":"EYE1 Paper 2","module":"BCMH","title":"The HIV-exposed infant with oral thrush","scenario":"A 6-week-old girl is brought to a clinic in Soweto. Her mother was diagnosed with HIV during pregnancy and started TLD\nat 20 weeks. Her last viral load, at 36 weeks, was 4 500 copies/mL. The infant was born at term, weighed 3.1 kg, received\nnevirapine at birth and is exclusively breastfed. Her HIV DNA PCR at birth was negative. Today she weighs 3.2 kg, has\nwhite plaques on her tongue and cheeks that scrape off, and has generalised lymphadenopathy. She is afebrile and her\nchest is clear.","questions":[{"number":1,"type":"SBA","q":"Why can a rapid HIV antibody test not be used to diagnose HIV infection in this infant?","options":["Infants cannot produce antibodies","Maternal IgG crosses the placenta and persists for up to 18 months, so antibody tests are positive in all exposed infants","Antibody tests are less accurate in girls","Breast milk contaminates the sample"],"answer":"B","explain":"Passive maternal IgG gives false-positive antibody results until about 18 months, so virological testing is used in infants."},{"number":2,"type":"SBA","q":"Which test is appropriate for diagnosing HIV in this infant today?","options":["Rapid HIV antibody test","CD4 count","HIV DNA PCR on a blood sample","Western blot"],"answer":"C","explain":"HIV DNA PCR detects proviral DNA in infected cells and is not affected by maternal antibody."},{"number":3,"type":"SBA","q":"Which factors most increase her risk of HIV infection?","options":["Maternal viral load that was not suppressed late in pregnancy, plus ongoing breastfeeding","Being born at term","Female sex","Receipt of nevirapine at birth"],"answer":"A","explain":"Transmission risk rises with high maternal viral load around delivery and during breastfeeding."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                                                                             Result\n\nHIV DNA PCR at birth                                                             Negative\n\nHIV DNA PCR today (6 weeks)                                                      Positive\n\nWhat is the most appropriate interpretation and action?","options":["Infection acquired around delivery or after birth; send a confirmatory sample and start ART without delay","False positive from maternal antibody; repeat at 18 months","Infection acquired in utero, so no action is needed","Contamination of the sample; discard the result"],"answer":"A","explain":"A negative birth PCR followed by a positive result suggests intrapartum or postnatal infection. A confirmatory test is sent, but ART is not delayed because early treatment reduces mortality."},{"number":5,"type":"SBA","q":"Which prophylaxis should be given to HIV-exposed infants from 6 weeks of age to prevent Pneumocystis\npneumonia?","options":["Isoniazid","Cotrimoxazole","Fluconazole","Azithromycin"],"answer":"B","explain":"Cotrimoxazole prevents PJP, which is a leading cause of death in infected infants of 3 to 6 months."},{"number":6,"type":"SBA","q":"The mother asks whether she should stop breastfeeding immediately. What is the most appropriate advice?","options":["Stop breastfeeding abruptly today","Continue to breastfeed, with maternal ART adherence and infant ARV prophylaxis, while the infant's status is clarified","Mix breast milk with formula","Wean onto cow's milk"],"answer":"B","explain":"Breastfeeding remains recommended with good maternal ART and infant prophylaxis. Safe formula feeding is often not feasible, and abrupt weaning increases infant morbidity."},{"number":7,"type":"VSAQ","q":"What is the programme that prevents HIV transmission from mother to child called (acronym)?","answer":"PMTCT.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"At what age (in months) can an HIV antibody test reliably diagnose HIV infection in a child?","answer":"18 months.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-02","paper":"EYE1 Paper 2","module":"BCMH","title":"Cough and weight loss in a man with HIV","scenario":"A 34-year-old man is diagnosed with HIV at a Johannesburg clinic. He has had a cough for 3 weeks with night sweats and\nweight loss. CD4 count is 41 cells/µL and HIV viral load is 450 000 copies/mL. Sputum Xpert MTB/RIF shows\nMycobacterium tuberculosis detected, rifampicin resistance not detected. He is started on first-line TB treatment (RHZE)\nand the plan is to start TLD (tenofovir, lamivudine, dolutegravir).","questions":[{"number":1,"type":"SBA","q":"Which drug interaction is most important when starting ART while he is on TB treatment?","options":["Isoniazid raises dolutegravir levels dangerously","Rifampicin induces enzymes that lower dolutegravir levels, so the dolutegravir dose is increased (twice daily)","Ethambutol blocks tenofovir absorption","Pyrazinamide inactivates lamivudine"],"answer":"B","explain":"Rifampicin induces CYP3A4 and UGT1A1, which lowers dolutegravir. The dose is given twice daily while on rifampicin."},{"number":2,"type":"SBA","q":"When should ART be started in this patient?","options":["After completing 6 months of TB treatment","Within 2 weeks of starting TB treatment, because his CD4 is below 50","Only when CD4 rises above 200","Never during TB treatment"],"answer":"B","explain":"Early ART reduces mortality in advanced HIV. It is started within 2 weeks when CD4 is below 50, and within 8 weeks otherwise."},{"number":3,"type":"SBA","q":"Four weeks after starting ART he develops fever and enlarging neck lymph nodes, while his cough improves. Which\nmechanism best explains this?","options":["Failure of TB treatment due to resistance","Restored immune responses mounting an inflammatory reaction to residual mycobacterial antigens","ART toxicity","A new Kaposi sarcoma"],"answer":"B","explain":"This is paradoxical TB-associated immune reconstitution inflammatory syndrome (IRIS), a recovering CD4 response to mycobacterial antigens."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTime                          CD4 (cells/µL)                  Viral load (copies/mL)\n\nBaseline                      41                              450 000\n\nWeek 8 on ART                 96                              380\n\nWhat is the best interpretation?","options":["Virological failure","Good virological and immunological response to ART","Drug resistance","Laboratory error"],"answer":"B","explain":"A fall of about 3 logs in viral load with CD4 recovery shows ART is working."},{"number":5,"type":"SBA","q":"What is the most appropriate management of his IRIS?","options":["Stop ART until symptoms settle","Stop TB treatment and restart later","Continue ART and TB treatment, exclude other causes and consider corticosteroids if severe","Add broad-spectrum antibiotics only"],"answer":"C","explain":"IRIS is not a reason to stop effective treatment. Exclude drug-resistant TB and other infections, and use steroids for significant disease."},{"number":6,"type":"SBA","q":"Which health-system intervention best improves outcomes for patients with TB and HIV?","options":["Integrated TB and HIV care delivered at the same facility and visit","Separate clinics on different days","Hospital-only treatment","Waiting until TB treatment is complete before offering HIV care"],"answer":"A","explain":"Integrated care improves adherence, reduces loss to follow-up and lowers mortality."},{"number":7,"type":"VSAQ","q":"What term describes rifampicin's effect on liver enzymes that lowers other drug levels?","answer":"Enzyme induction (inducer).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which first-line TB drug turns body fluids orange-red?","answer":"Rifampicin.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-03","paper":"EYE1 Paper 2","module":"BCMH","title":"Fever after a holiday","scenario":"A 27-year-old teacher returned 10 days ago from a holiday in northern KwaZulu-Natal and took no malaria prophylaxis.\nShe presents with 2 days of fever, chills, myalgia, headache and one episode of vomiting. She is alert. Temperature 38.9\n°C, HR 104/min, BP 112/70 mmHg, SpO2 98% on room air, glucose 5.2 mmol/L. She is not jaundiced. A malaria rapid test\nshows P. falciparum.","questions":[{"number":1,"type":"SBA","q":"What event is responsible for her cyclical fever and rigors?","options":["Sporozoite entry into hepatocytes","Rupture of schizont-infected red cells releasing merozoites and pyrogenic mediators","Hypnozoite activation","Mosquito saliva toxins"],"answer":"B","explain":"Fever is triggered when infected red cells burst and release parasite material, which activates macrophages to release cytokines."},{"number":2,"type":"SBA","q":"Data interpretation\n\nTest                                                                  Result\n\nParasitaemia (thin film)                                              0.4%\n\nHaemoglobin                                                           11.8 g/dL\n\nPlatelets                                                             95 × 10⁹/L\n\nGlucose                                                               5.2 mmol/L\n\nCreatinine                                                            80 µmol/L\n\nBilirubin                                                             12 µmol/L\n\nWhat is the correct classification?","options":["Severe malaria","Uncomplicated falciparum malaria with mild thrombocytopenia","Bacterial sepsis","Vivax malaria"],"answer":"B","explain":"She has no impaired consciousness, hypoglycaemia, renal impairment or high parasitaemia. Mild thrombocytopenia is common."},{"number":3,"type":"SBA","q":"Which treatment is most appropriate?","options":["IV artesunate","Oral artemether-lumefantrine taken with fatty food or milk","Chloroquine alone","Primaquine alone"],"answer":"B","explain":"Oral artemisinin-based combination therapy treats uncomplicated falciparum malaria. Lumefantrine needs fat for absorption."},{"number":4,"type":"SBA","q":"Why are artemisinin drugs always given in combination?","options":["To increase side effects","A fast-acting artemisinin reduces parasite load, while a longer-acting partner clears the rest and limits resistance","Artemisinins are unstable alone","To reduce cost"],"answer":"B","explain":"Combination therapy gives rapid clearance and protects against emerging resistance."},{"number":5,"type":"SBA","q":"Which finding on review would require urgent escalation to hospital care?","options":["Mild headache","Persistent vomiting preventing oral treatment, drowsiness or hypoglycaemia","Low-grade fever on day 2 of treatment","Myalgia"],"answer":"B","explain":"Inability to tolerate oral therapy or any danger sign changes the classification to severe malaria needing IV artesunate."},{"number":6,"type":"SBA","q":"Which advice best reduces her risk on a future trip to an endemic area?","options":["Chemoprophylaxis plus bite prevention (nets, repellent, protective clothing)","Avoid all outdoor activity during the day only","Take antipyretics","Rely on a previous infection for immunity"],"answer":"A","explain":"Malaria prevention combines awareness, bite avoidance, chemoprophylaxis and early diagnosis."},{"number":7,"type":"VSAQ","q":"Which genus of mosquito transmits malaria?","answer":"Anopheles.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-04","paper":"EYE1 Paper 2","module":"BCMH","title":"Headache and drowsiness in HIV","scenario":"A 39-year-old woman with HIV defaulted on ART a year ago. Her last CD4 count was 68 cells/µL. She presents with 2\nweeks of worsening headache and vomiting, and is now drowsy. Temperature 38.2 °C, GCS 13/15, BP 120/76 mmHg,\nmild neck stiffness, no focal neurology.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely cause?","options":["Neisseria meningitidis","Cryptococcus neoformans","Herpes simplex virus","Streptococcus pneumoniae"],"answer":"B","explain":"Cryptococcal meningitis is the commonest cause of meningitis in adults with advanced HIV (CD4 below 100)."},{"number":2,"type":"SBA","q":"Which feature of the organism helps it evade host defences?","options":["Polysaccharide capsule that inhibits phagocytosis","Production of exotoxin","Spore formation","Intracellular replication in neutrophils"],"answer":"A","explain":"The capsule resists phagocytosis. CD4 deficiency also impairs the granulomatous response."},{"number":3,"type":"SBA","q":"Which test is the most useful rapid diagnostic test?","options":["Serum or CSF cryptococcal antigen (CrAg) lateral flow assay","Gram stain only","Chest X-ray","Serum CRP"],"answer":"A","explain":"CrAg is highly sensitive and specific and gives results within minutes."},{"number":4,"type":"SBA","q":"Data interpretation\n\nCSF test                                    Result\n\nOpening pressure                            38 cmH₂O (normal < 20)\n\nWhite cells                                 8/µL, lymphocytes\n\nProtein                                     0.6 g/L (mildly raised)\n\nGlucose                                     2.0 mmol/L (blood 5.5)\n\nIndia ink                                   Positive\n\nCrAg                                        Positive\n\nWhat is the correct interpretation?","options":["Bacterial meningitis","Viral meningitis","Cryptococcal meningitis with raised intracranial pressure","Normal CSF"],"answer":"C","explain":"Positive India ink and CrAg with a raised opening pressure and low CSF glucose confirm cryptococcal meningitis."},{"number":5,"type":"SBA","q":"What is the best way to manage the raised pressure?","options":["Repeated therapeutic lumbar punctures to lower the CSF pressure","High-dose dexamethasone","Mannitol infusion","Acetazolamide"],"answer":"A","explain":"Raised pressure is a major cause of morbidity. Drainage by serial LPs is recommended, while steroids, mannitol and acetazolamide do not help."},{"number":6,"type":"SBA","q":"When should ART be restarted?","options":["On the same day as antifungal treatment","After 4 to 6 weeks of antifungal treatment","Never","After 12 months"],"answer":"B","explain":"Starting ART too early increases the risk of IRIS and death in cryptococcal meningitis."},{"number":7,"type":"VSAQ","q":"Which structure appears as a halo around yeast cells on India ink?","answer":"Capsule.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-05","paper":"EYE1 Paper 2","module":"BCMH","title":"Rash and mouth sores after starting a new drug","scenario":"A 31-year-old man, newly diagnosed with HIV, started cotrimoxazole prophylaxis 10 days ago. He presents with fever,\npainful eroded lips and oral mucosa, red sore eyes, and a widespread dusky rash with target-like lesions and blisters on\nthe trunk. Gentle sideways pressure on his skin causes the top layer to slide off. Temperature 38.8 °C, HR 108/min, BP\n118/72 mmHg, alert.","questions":[{"number":1,"type":"SBA","q":"Which type of hypersensitivity reaction explains this presentation?","options":["Type I","Type II","Type III","Type IV (T-cell-mediated, delayed)"],"answer":"D","explain":"Severe cutaneous reactions to drugs are delayed T-cell-mediated reactions occurring 1 to 3 weeks after starting the drug."},{"number":2,"type":"SBA","q":"Which finding most strongly indicates a severe cutaneous adverse reaction rather than a simple rash?","options":["Mild itching","Mucosal erosions with skin pain and blistering","Low-grade fever","A few pink macules"],"answer":"B","explain":"Mucosal involvement, skin pain, blistering and a positive Nikolsky sign suggest SJS/TEN."},{"number":3,"type":"SBA","q":"Data interpretation\n\nFinding                                             Result\n\nEpidermal detachment                                8% of body surface area\n\nMucosal involvement                                 Oral, ocular\n\nNikolsky sign                                       Positive\n\nClassification: SJS is under 10% detachment, SJS/TEN overlap 10 to 30%, TEN over 30%. Which diagnosis is correct?","options":["Stevens-Johnson syndrome","Toxic epidermal necrolysis","Contact dermatitis","Simple morbilliform drug rash"],"answer":"A","explain":"8% detachment with mucosal involvement is Stevens-Johnson syndrome."},{"number":4,"type":"SBA","q":"What is the most important first step in his management?","options":["Continue cotrimoxazole and add steroids","Stop the suspected drug and admit for supportive care","Apply topical antifungals","Discharge on antihistamines"],"answer":"B","explain":"Stopping the culprit drug is the key step. Supportive care includes fluids, wound care, pain control, infection surveillance and eye review."},{"number":5,"type":"SBA","q":"Why should he never be rechallenged with the drug?","options":["Memory T cells will produce a faster, more severe reaction","The drug becomes ineffective","The reaction was not immune-mediated","It will cause hypertension"],"answer":"A","explain":"Re-exposure activates memory T cells, causing a more rapid and potentially fatal reaction."},{"number":6,"type":"SBA","q":"What is the most appropriate record-keeping and safety step?","options":["No documentation is required","Document the allergy in his record, inform him and report the adverse drug reaction","Tell him only to avoid sulphur-containing foods","Document only if the reaction recurs"],"answer":"B","explain":"Clear documentation and ADR reporting protect the patient and others (patient safety and professionalism)."},{"number":7,"type":"VSAQ","q":"Which T-cell type mediates keratinocyte killing in this reaction?","answer":"Cytotoxic (CD8+) T cells.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-06","paper":"EYE1 Paper 2","module":"CVS","title":"Severe headache and very high blood pressure","scenario":"A 48-year-old taxi driver presents with 6 hours of severe headache, blurred vision and vomiting. He has known\nhypertension but stopped his medication 3 months ago because he could not afford the clinic transport. BP is 230/135\nmmHg in the right arm and 228/132 mmHg in the left. HR 88/min. Fundoscopy shows flame haemorrhages, cotton-wool\nspots and swelling of the optic discs. Urine dipstick: protein 2+, blood 1+.","questions":[{"number":1,"type":"SBA","q":"Which feature most clearly distinguishes a hypertensive emergency from severe asymptomatic hypertension?","options":["The height of the blood pressure alone","Evidence of acute target-organ damage","A history of non-adherence","The patient's age"],"answer":"B","explain":"Emergency is defined by acute end-organ damage (retina, brain, kidney, heart), not the number alone."},{"number":2,"type":"SBA","q":"Which mechanism best explains his retinal changes?","options":["Pressure surges overwhelm autoregulation, causing endothelial injury, fibrinoid necrosis and leakage","Infection of the retina","Primary optic neuritis","Retinal artery embolism"],"answer":"A","explain":"Severe hypertension damages arterioles, causing haemorrhages and exudates, and raised pressure or ischaemia causes papilloedema."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                          Result\n\nCreatinine                    190 µmol/L (85 six months ago)\n\nUrine dipstick                Protein 2+, blood 1+\n\nECG                           Left ventricular hypertrophy with strain\n\nTroponin                      Normal\n\nPotassium                     4.2 mmol/L\n\nWhat is the best interpretation?","options":["Hypertensive urgency without organ damage","Hypertensive emergency with retinal and renal target-organ damage","White-coat hypertension","Isolated primary kidney disease"],"answer":"B","explain":"Retinopathy, a rising creatinine with proteinuria and LVH confirm hypertensive emergency."},{"number":4,"type":"SBA","q":"What is the safest approach to lowering his blood pressure?","options":["Normalise it within minutes with a sublingual drug","Controlled, gradual reduction in a monitored setting (no more than about 25% in the first hour)","Withhold treatment until the headache resolves","Give oral diuretics only and send him home"],"answer":"B","explain":"Cerebral and renal autoregulation are reset to high pressure. Rapid falls risk stroke, blindness and renal injury."},{"number":5,"type":"SBA","q":"Which long-term regimen is most appropriate once he is stable?","options":["No treatment if asymptomatic","Combination therapy such as an ACE inhibitor or ARB with a calcium-channel blocker and/or thiazide-like diuretic","A β-blocker alone","Aspirin alone"],"answer":"B","explain":"Combination therapy is preferred for stage 2 hypertension, and ACE inhibitors are especially useful with proteinuria or kidney injury."},{"number":6,"type":"SBA","q":"Which approach best addresses his stopping of medication?","options":["Scold him about non-compliance","Explore the barriers (cost, transport, beliefs), and arrange practical solutions such as community dispensing","Provide a leaflet only","Avoid discussing adherence"],"answer":"B","explain":"Patient-centred care explores social barriers and shares decisions."},{"number":7,"type":"VSAQ","q":"Which arteriolar change is typical of malignant hypertension?","answer":"Fibrinoid necrosis.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the term for the ability of organs to keep blood flow constant across a range of pressures?","answer":"Autoregulation.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-07","paper":"EYE1 Paper 2","module":"CVS","title":"Sudden-onset palpitations","scenario":"A 24-year-old woman presents with 40 minutes of sudden-onset palpitations while studying, with mild chest tightness\nand light-headedness but no syncope. She has had shorter episodes before. Pulse 190/min and regular, BP 112/70\nmmHg, RR 20/min, SpO2 99%, chest clear, JVP normal. ECG: regular narrow-complex tachycardia at 190/min with no\nvisible P waves.","questions":[{"number":1,"type":"SBA","q":"Which mechanism most commonly underlies this rhythm?","options":["Re-entry circuit involving the AV node","Multiple wavelets of atrial depolarisation","Ventricular scar re-entry","Failure of the sinus node"],"answer":"A","explain":"Sudden onset and termination with a regular narrow-complex tachycardia suggest AV nodal re-entry."},{"number":2,"type":"SBA","q":"What does the narrow QRS complex tell you?","options":["The rhythm arises above the ventricles, with ventricles activated through the normal His-Purkinje system","The rhythm arises in the ventricle","There is complete heart block","There is bundle branch block"],"answer":"A","explain":"Narrow QRS means supraventricular origin with normal ventricular conduction."},{"number":3,"type":"SBA","q":"Which first-line intervention is appropriate in this stable patient?","options":["Immediate DC cardioversion","Vagal manoeuvres (e.g. modified Valsalva)","IV amiodarone","Oral digoxin"],"answer":"B","explain":"Vagal manoeuvres slow AV conduction and terminate many re-entry circuits."},{"number":4,"type":"SBA","q":"The manoeuvres fail. Which drug is given next and how does it work?","options":["IV adenosine; it briefly blocks AV nodal conduction","IV lignocaine; it blocks sodium channels in the ventricle","Oral warfarin; it prevents clots","IV atropine; it speeds the AV node"],"answer":"A","explain":"Adenosine is given as a rapid bolus and transiently blocks the AV node, which terminates re-entry."},{"number":5,"type":"SBA","q":"Which finding would mandate synchronised DC cardioversion?","options":["Palpitations alone","Haemodynamic instability (shock, syncope, ongoing ischaemic pain or acute heart failure)","A history of previous episodes","Age under 30"],"answer":"B","explain":"Unstable patients with tachyarrhythmia need immediate synchronised cardioversion."},{"number":6,"type":"SBA","q":"Data interpretation\nECG after adenosine: \"Sinus rhythm 78/min. PR interval 100 ms (short). Slurred upstroke at the start of the QRS (delta\nwave). QRS 130 ms.\"\n\nWhat is the correct interpretation?","options":["Normal ECG","Pre-excitation (Wolff-Parkinson-White pattern) requiring cardiology referral","First-degree heart block","Left bundle branch block"],"answer":"B","explain":"A short PR and delta wave indicate an accessory pathway. She needs specialist assessment and likely ablation, and AV-nodal blockers should be avoided in pre-excited AF."},{"number":7,"type":"VSAQ","q":"What is the accessory pathway in WPW called?","answer":"Bundle of Kent.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which ambulatory test can capture infrequent palpitations?","answer":"Holter monitor (ambulatory ECG).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-08","paper":"EYE1 Paper 2","module":"CVS","title":"Poor feeding and fast breathing in an infant","scenario":"A 6-week-old boy is brought with 3 weeks of poor feeding, sweating during feeds and fast breathing. He was born at\nterm and has never been blue. Weight is below the 3rd percentile. RR 62/min, HR 170/min, SpO2 98% on room air, liver\nedge 4 cm below the costal margin. There is a harsh pansystolic murmur at the left lower sternal edge with a thrill. CXR\nshows cardiomegaly and increased pulmonary vascular markings.","questions":[{"number":1,"type":"SBA","q":"Which lesion is most likely?","options":["Tetralogy of Fallot","Ventricular septal defect","Patent ductus arteriosus","Coarctation of the aorta"],"answer":"B","explain":"An acyanotic infant with a pansystolic murmur at the left lower sternal edge, heart failure and plethoric lungs fits a VSD."},{"number":2,"type":"SBA","q":"Which haemodynamic process produces his heart failure?","options":["Right-to-left shunt reducing oxygenation","Left-to-right shunt causing pulmonary overcirculation and left heart volume overload","Obstruction of the aorta","Pulmonary vein stenosis"],"answer":"B","explain":"Blood flows from the high-pressure left ventricle into the right ventricle and lungs, overloading the left heart."},{"number":3,"type":"SBA","q":"Why do symptoms begin at 4 to 8 weeks rather than at birth?","options":["The defect forms after birth","Pulmonary vascular resistance falls over the first weeks, increasing the left-to-right shunt","Maternal antibodies mask symptoms","The ductus opens at 4 weeks"],"answer":"B","explain":"As pulmonary resistance drops, more blood is shunted through the defect."},{"number":4,"type":"SBA","q":"Data interpretation\nEchocardiogram report: \"8 mm perimembranous VSD with left-to-right flow. Dilated left atrium and left ventricle.\nEstimated right ventricular systolic pressure 40 mmHg (normal below 30). Normal LV function. No other defects.\"\n\nWhat is the best interpretation?","options":["Small, haemodynamically insignificant defect","Large defect with volume overload and early pulmonary hypertension needing specialist referral and likely closure","Tetralogy of Fallot","Normal study"],"answer":"B","explain":"A large defect with a dilated left heart and raised right-sided pressure needs timely paediatric cardiology and surgical referral."},{"number":5,"type":"SBA","q":"What is the most appropriate initial management in the clinic?","options":["Diuretic therapy, nutritional support and early referral to paediatric cardiology","Antibiotics only","Prostaglandin E1 infusion","Reassurance and review at 1 year"],"answer":"A","explain":"Diuretics relieve congestion, feeding support helps growth, and referral allows timely repair."},{"number":6,"type":"SBA","q":"Why may a small restrictive VSD produce a louder murmur than a large VSD?","options":["Small defects have high-velocity turbulent flow, while large defects equalise pressure and reduce the murmur","Small defects cause more blood to shunt","Large defects have no flow","Murmur loudness does not depend on flow velocity"],"answer":"A","explain":"A restrictive defect has a high pressure gradient and loud murmur. A large defect equalises pressures and can be quiet, signalling pulmonary hypertension."},{"number":7,"type":"VSAQ","q":"What is the syndrome of shunt reversal due to pulmonary hypertension called?","answer":"Eisenmenger syndrome.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-09","paper":"EYE1 Paper 2","module":"CVS","title":"High blood pressure in a schoolgirl","scenario":"A 12-year-old girl is referred by the school nurse with a blood pressure of 150/90 mmHg. She has occasional headaches,\nleg tiredness after exercise and cold feet. She is short for her age and has not started puberty. Femoral pulses are weak\nand delayed compared with the radial pulses. There is a systolic murmur heard between the shoulder blades. CXR shows\nnotching of the inferior borders of the ribs.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains her hypertension?","options":["Obstruction to aortic flow raising upper-body pressure, with renal hypoperfusion activating the renin-angiotensin system","Primary hyperaldosteronism","Phaeochromocytoma","Left ventricular failure"],"answer":"A","explain":"Narrowing of the aorta increases pressure proximally and reduces renal perfusion, so the RAAS is activated."},{"number":2,"type":"SBA","q":"Which examination finding is the most specific for this condition?","options":["Radiofemoral delay","Raised JVP","Ankle oedema","Wide pulse pressure"],"answer":"A","explain":"Radiofemoral delay reflects blood reaching the legs late through collaterals."},{"number":3,"type":"SBA","q":"Data interpretation\n\nSite                                                        Blood pressure\n\nRight arm                                                   160/95 mmHg\n\nLeft arm                                                    150/90 mmHg\n\nRight leg (popliteal)                                       95/60 mmHg\n\nWhat is the best interpretation?","options":["Normal, arm and leg pressures should differ","Upper-limb hypertension with lower-limb hypotension, consistent with coarctation of the aorta","Measurement error only","Aortic regurgitation"],"answer":"B","explain":"Leg pressure is normally equal to or higher than arm pressure, so a large gradient suggests coarctation."},{"number":4,"type":"SBA","q":"What causes the rib notching on her chest X-ray?","options":["Bone infection","Enlarged, tortuous intercostal collateral arteries eroding the lower rib borders","Vitamin D deficiency","Tumour deposits"],"answer":"B","explain":"Collateral intercostal arteries enlarge to bypass the narrowing and erode the ribs."},{"number":5,"type":"SBA","q":"Which condition is most strongly associated with this lesion?","options":["Down syndrome","Turner syndrome","Marfan syndrome","Fragile X syndrome"],"answer":"B","explain":"Coarctation and bicuspid aortic valve are associated with Turner syndrome (45,X)."},{"number":6,"type":"SBA","q":"Which investigation best confirms the diagnosis and defines the gradient?","options":["Echocardiography with Doppler (or CT angiography)","Resting ECG only","Serum troponin","Spirometry"],"answer":"A","explain":"Echo with Doppler shows the site and the pressure gradient of the narrowing."},{"number":7,"type":"VSAQ","q":"Which drug is used to keep the ductus open in a newborn with critical coarctation?","answer":"Prostaglandin E1 (alprostadil).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-10","paper":"EYE1 Paper 2","module":"CVS","title":"Chest pain and cold, clammy collapse","scenario":"A 58-year-old man arrives with 3 hours of crushing central chest pain and sweating. He is now confused. BP 78/50\nmmHg, HR 118/min, RR 30/min, SpO2 88% on room air. His hands and feet are cold and clammy. JVP is raised and there\nare crackles to the mid-zones bilaterally. ECG: ST elevation in V1 to V5 with developing Q waves.","questions":[{"number":1,"type":"SBA","q":"Which type of shock is present?","options":["Hypovolaemic","Distributive (septic)","Cardiogenic","Neurogenic"],"answer":"C","explain":"A failing pump with raised filling pressures (JVP, pulmonary oedema) and low output gives cardiogenic shock."},{"number":2,"type":"SBA","q":"Which mechanism explains his cold peripheries?","options":["Vasodilation","Reduced cardiac output with compensatory vasoconstriction","Anaemia","Fever"],"answer":"B","explain":"Low output triggers sympathetic and RAAS activation, causing peripheral vasoconstriction."},{"number":3,"type":"SBA","q":"Which coronary artery is most likely occluded?","options":["Right coronary artery","Left circumflex artery","Left anterior descending artery","Posterior descending artery"],"answer":"C","explain":"ST elevation in V1 to V5 indicates an anterior infarct from LAD occlusion."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                               Result\n\nLactate                            6.4 mmol/L\n\nCreatinine                         160 µmol/L\n\nTroponin I                         18 000 ng/L\n\nEchocardiogram                     LVEF 20%, anterior wall akinesis\n\nWhat is the best interpretation?","options":["Small infarct with mild dysfunction","Extensive anterior infarction with severe LV failure and tissue hypoperfusion","Pulmonary embolism","Pericarditis"],"answer":"B","explain":"A very high troponin, LVEF of 20%, raised lactate and rising creatinine indicate pump failure with organ hypoperfusion."},{"number":5,"type":"SBA","q":"Which intervention gives the greatest survival benefit?","options":["Early revascularisation (primary PCI)","High-dose diuretic alone","Oral aspirin alone","Nitrate infusion"],"answer":"A","explain":"Emergency revascularisation improves survival in cardiogenic shock complicating STEMI."},{"number":6,"type":"SBA","q":"Which action is inappropriate?","options":["Large-volume IV crystalloid boluses","Oxygen and ventilatory support as needed","Inotrope or vasopressor support","Urgent transfer to a PCI-capable centre"],"answer":"A","explain":"He is already volume overloaded, so large fluid boluses will worsen pulmonary oedema."},{"number":7,"type":"VSAQ","q":"Which biomarker confirms myocardial necrosis?","answer":"Troponin.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the time measure from hospital arrival to primary PCI called?","answer":"Door-to-balloon time.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-11","paper":"EYE1 Paper 2","module":"CVS","title":"A swollen calf after surgery","scenario":"A 62-year-old woman presents 6 days after a total hip replacement with 2 days of left calf pain and swelling. She was\ndischarged on day 3 without thromboprophylaxis. The left calf is 4 cm larger than the right, with pitting oedema,\ntenderness along the deep veins and dilated superficial veins. HR 88/min, SpO2 97%, no chest symptoms.","questions":[{"number":1,"type":"SBA","q":"Which components of Virchow's triad are present?","options":["Stasis, endothelial injury and hypercoagulability","Stasis only","Hyperviscosity only","Endothelial injury only"],"answer":"A","explain":"Immobility causes stasis, surgery causes endothelial injury, and the post-operative state is hypercoagulable."},{"number":2,"type":"SBA","q":"Which mechanism best explains the leg swelling?","options":["Venous obstruction raising hydrostatic pressure with fluid moving into the interstitium","Lymphatic malformation","Reduced albumin synthesis","Right heart failure"],"answer":"A","explain":"Thrombus blocks venous return, increasing capillary hydrostatic pressure."},{"number":3,"type":"SBA","q":"Which investigation should be done first to confirm the diagnosis?","options":["Venous compression duplex ultrasound","Chest X-ray","ECG","Skin biopsy"],"answer":"A","explain":"Compression ultrasound is the first-line imaging test for suspected DVT."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTest                           Result\n\nDuplex ultrasound              Left popliteal vein non-compressible with echogenic thrombus and\n                               absent flow\n\nD-dimer                        4 200 ng/mL (normal < 500)\n\nWhat is the best interpretation?","options":["Confirmed proximal DVT; the raised D-dimer is non-specific after surgery","Normal study","Superficial thrombophlebitis only","Baker's cyst"],"answer":"A","explain":"Ultrasound confirms DVT. D-dimer is expected to be raised after surgery and adds nothing."},{"number":5,"type":"SBA","q":"What is the most appropriate treatment?","options":["Compression bandage alone","Therapeutic anticoagulation (LMWH then oral anticoagulant)","Antibiotics","Bed rest alone"],"answer":"B","explain":"Anticoagulation prevents propagation and embolisation."},{"number":6,"type":"SBA","q":"Which new symptom would suggest a major complication and require urgent review?","options":["Sudden breathlessness or pleuritic chest pain","Mild calf itching","Leg tiredness","Dry skin"],"answer":"A","explain":"These suggest embolisation of the clot to the pulmonary arteries (PE)."},{"number":7,"type":"VSAQ","q":"What is the chronic complication caused by venous valve damage after DVT?","answer":"Post-thrombotic syndrome.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-12","paper":"EYE1 Paper 2","module":"RESP","title":"Fast breathing in a young infant","scenario":"A 5-month-old girl born at 34 weeks is brought with 3 days of runny nose, then cough, fast breathing and wheeze. She is\nfeeding less than half her usual amount. Her mother smokes and she attends a crèche. Temperature 37.9 °C, RR 66/min,\nHR 168/min, SpO2 90% on room air. She has nasal flaring, subcostal recession, bilateral fine crackles and expiratory\nwheeze.","questions":[{"number":1,"type":"SBA","q":"Which pathogen is the most likely cause?","options":["Respiratory syncytial virus","Mycobacterium tuberculosis","Streptococcus pneumoniae","Pneumocystis jirovecii"],"answer":"A","explain":"RSV is the commonest cause of bronchiolitis in infants."},{"number":2,"type":"SBA","q":"Which pathological process explains her wheeze and hypoxaemia?","options":["Viral infection of bronchiolar epithelium with necrosis, oedema and mucus plugging, causing small-airway obstruction","Lobar alveolar consolidation","Caseating granulomas","Chronic eosinophilic inflammation"],"answer":"A","explain":"Infected epithelial cells slough and block the small airways, causing air trapping and atelectasis."},{"number":3,"type":"SBA","q":"Why do infants become so unwell with a small amount of airway swelling?","options":["Airway resistance rises steeply as the radius falls, so a small narrowing causes a large increase in resistance","Their lungs have more cilia","They have larger airways","They have a better immune response"],"answer":"A","explain":"Resistance is proportional to 1/r⁴, so tiny airways are very vulnerable."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTime                 RR      HR      SpO2           Work of breathing                              Feeds\n\nArrival              66      168     90% room       Moderate recession                             50%\n                                     air\n\n4 h (on oxygen, 2    74      186     93%            Severe recession and grunting, one 15-         20%\nL/min)                                              second apnoea\n\nWhat is the correct interpretation?","options":["Improving, so continue observation","Deteriorating with fatigue and apnoea, requiring urgent escalation (HDU/ICU and respiratory support)","Normal course of illness","Treat with antibiotics only"],"answer":"B","explain":"Rising RR and HR, grunting, apnoea and falling intake mean impending respiratory failure."},{"number":5,"type":"SBA","q":"What is the most appropriate management?","options":["Supportive care: oxygen, hydration or feeding support and suctioning","Routine antibiotics and oral steroids","Regular nebulised salbutamol","Chest physiotherapy to clear mucus"],"answer":"A","explain":"Bronchiolitis is treated supportively. Antibiotics, steroids and bronchodilators have no proven benefit."},{"number":6,"type":"SBA","q":"Which measure best reduces the spread of this infection in the ward?","options":["Hand hygiene and cohorting or isolating infected infants","Giving antibiotics to all contacts","Sharing equipment between infants","Allowing unlimited visitors"],"answer":"A","explain":"RSV spreads by droplets and contaminated surfaces."},{"number":7,"type":"VSAQ","q":"Name a monoclonal antibody used to prevent severe RSV disease in high-risk infants.","answer":"Palivizumab (or nirsevimab).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the mainstay of treatment for bronchiolitis?","answer":"Supportive care.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-13","paper":"EYE1 Paper 2","module":"RESP","title":"Facial pain and nasal discharge","scenario":"A 29-year-old woman has had 11 days of nasal blockage, thick yellow-green nasal discharge, right cheek pain and\npressure that worsens on bending forward, and aching in her upper teeth. She improved around day 5 and then\nworsened with new fever. Temperature 37.9 °C. There is tenderness over the right maxillary sinus and purulent\ndischarge in the middle meatus. There is no eye swelling or visual change.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains her symptoms?","options":["Obstruction of the sinus drainage (ostiomeatal complex) by mucosal oedema, with mucus stasis and secondary infection","Primary immune deficiency","Nasal polyps only","Foreign body"],"answer":"A","explain":"Blocked ostia impair mucociliary clearance, so mucus stagnates and becomes infected."},{"number":2,"type":"SBA","q":"Which feature suggests bacterial rather than viral sinusitis?","options":["Symptoms for 3 days","Persistence beyond 10 days or double worsening after initial improvement","Mild sore throat","Clear watery discharge"],"answer":"B","explain":"Persistent symptoms beyond 10 days or a \"double-sickening\" course favours a bacterial cause."},{"number":3,"type":"SBA","q":"Data interpretation\n\nDay              Symptoms\n\n1 to 4           Sore throat, sneezing, watery discharge\n\n5 to 6           Partial improvement\n\n7 to 11          Worsening: purulent discharge, unilateral facial pain, fever\n\nWhat does this pattern suggest?","options":["Allergic rhinitis","Acute bacterial rhinosinusitis","Common cold","Chronic sinusitis"],"answer":"B","explain":"Improvement followed by worsening with fever and purulent discharge is typical of bacterial superinfection."},{"number":4,"type":"SBA","q":"What is the most appropriate management?","options":["Analgesia, saline irrigation, intranasal corticosteroid, and an antibiotic such as amoxicillin given the persistence beyond 10 days","No treatment of any kind","IV antibiotics and admission","Oral decongestants for 3 weeks"],"answer":"A","explain":"Antibiotics are reserved for persistent or severe disease, and supportive therapy helps symptoms."},{"number":5,"type":"SBA","q":"Which new finding would be a red flag requiring urgent referral?","options":["Nasal blockage","Periorbital swelling, painful eye movements, proptosis or reduced vision","Mild fever","Cheek tenderness"],"answer":"B","explain":"These signs suggest orbital cellulitis or intracranial spread and need urgent hospital assessment."},{"number":6,"type":"SBA","q":"Which feature best distinguishes allergic rhinitis from this illness?","options":["Itching, sneezing and clear watery discharge with pale boggy turbinates, without fever","Fever and facial pain","Purulent discharge","Unilateral tenderness"],"answer":"A","explain":"Allergic rhinitis is a Type I hypersensitivity with itch, sneezing and watery rhinorrhoea."},{"number":7,"type":"VSAQ","q":"Which antibody class mediates allergic rhinitis?","answer":"IgE.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-14","paper":"EYE1 Paper 2","module":"RESP","title":"Breathlessness with fever and loss of smell","scenario":"A 52-year-old unvaccinated man with type 2 diabetes and obesity (BMI 36) presents with 6 days of fever, dry cough,\nmyalgia and loss of smell, and is now breathless at rest. Temperature 38.5 °C, HR 108/min, RR 30/min, BP 130/80 mmHg,\nSpO2 86% on room air. There are bilateral crackles. A SARS-CoV-2 PCR is positive.","questions":[{"number":1,"type":"SBA","q":"How does the virus enter human cells?","options":["Spike protein binds ACE2 receptors (with TMPRSS2 priming) on host cells","It binds CD4 receptors","It enters via the LDL receptor","It enters by phagocytosis only"],"answer":"A","explain":"The SARS-CoV-2 spike binds ACE2, which is abundant on type II pneumocytes."},{"number":2,"type":"SBA","q":"Which pathological process best explains his hypoxaemia?","options":["Diffuse alveolar damage with hyaline membranes and endothelial injury, causing V/Q mismatch and shunt","Bronchospasm","Granuloma formation","Pulmonary fibrosis within days"],"answer":"A","explain":"Severe disease causes diffuse alveolar damage and microvascular thrombosis."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                            Result\n\nChest X-ray                     Bilateral peripheral patchy opacities (ground-glass)\n\nCRP                             180 mg/L\n\nLymphocyte count                0.7 × 10⁹/L (low)\n\nD-dimer                         2.8 mg/L (raised)\n\nFerritin                        Raised\n\nWhat is the best interpretation?","options":["Mild viral illness","Severe COVID-19 pneumonia with hyperinflammation and a prothrombotic state","Bacterial lobar pneumonia","Pulmonary oedema from heart failure"],"answer":"B","explain":"Lymphopenia, a high CRP, ferritin and D-dimer, and bilateral ground-glass changes show severe inflammatory disease."},{"number":4,"type":"SBA","q":"Which combination of treatments is most appropriate?","options":["Oxygen, dexamethasone and prophylactic anticoagulation","Antibiotics alone","Oral antihistamines","Chest physiotherapy only"],"answer":"A","explain":"Oxygen is the priority, and corticosteroids reduce mortality in hypoxic patients. Anticoagulation reduces thrombotic risk."},{"number":5,"type":"SBA","q":"Which explains the raised D-dimer and the need for thromboprophylaxis?","options":["Endothelial injury and a hypercoagulable state causing microvascular and venous thrombosis","Bleeding disorder","Hepatic failure","Dehydration alone"],"answer":"A","explain":"COVID-19 causes endothelial damage, inflammation and clotting activation."},{"number":6,"type":"SBA","q":"Which population measure best reduces severe disease and hospitalisation?","options":["Vaccination","Antibiotic prophylaxis","School closures alone","Vitamin supplements only"],"answer":"A","explain":"Vaccination markedly lowers the risk of severe disease and death."},{"number":7,"type":"VSAQ","q":"What is the syndrome of acute hypoxaemic respiratory failure with bilateral infiltrates called?","answer":"ARDS (acute respiratory distress syndrome).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which body position can improve oxygenation in a hypoxic COVID-19 patient?","answer":"Prone position.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-15","paper":"EYE1 Paper 2","module":"RESP","title":"Cough and fast breathing in a toddler","scenario":"An 18-month-old boy is brought to a clinic in Mamelodi with 3 days of cough, fever and fast breathing. His\nimmunisations are up to date. He is alert, drinking well, has no convulsions or stridor, and no chest wall indrawing.\nTemperature 38.6 °C, RR 52/min, SpO2 93% on room air. There are crackles at the right base.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely bacterial cause?","options":["Streptococcus pneumoniae","Pneumocystis jirovecii","Mycobacterium tuberculosis","Candida albicans"],"answer":"A","explain":"S. pneumoniae is the commonest bacterial cause of childhood pneumonia."},{"number":2,"type":"SBA","q":"Which mechanism best explains the fast breathing?","options":["Reduced lung compliance, hypoxaemia and acidosis stimulating the respiratory centre","Airway obstruction by a foreign body","Anxiety","Cardiac failure"],"answer":"A","explain":"Inflamed, stiff lungs and low oxygen drive an increased respiratory rate."},{"number":3,"type":"SBA","q":"Data interpretation\n\nFinding                              Patient        Threshold\n\nRespiratory rate                     52/min         ≥ 40/min (12 to 59 months)\n\nSpO2                                 93%            < 90% suggests severe disease\n\nGeneral danger signs                 None           Present = severe\n\nWhat is the correct classification and action?","options":["Pneumonia without danger signs: oral amoxicillin, caregiver counselling and review in 2 days","Very severe disease: urgent referral","Cough or cold: no antibiotic","Asthma: salbutamol only"],"answer":"A","explain":"Fast breathing with fever and crackles, in a child with no danger signs and SpO2 above 90%, is treated at the clinic with oral amoxicillin and follow-up."},{"number":4,"type":"SBA","q":"What is the most appropriate treatment?","options":["Oral amoxicillin","Oral cotrimoxazole only","IV ceftriaxone for all children","No treatment"],"answer":"A","explain":"Amoxicillin is first-line for non-severe childhood pneumonia."},{"number":5,"type":"SBA","q":"Which finding would change the classification to severe pneumonia needing referral?","options":["Mild cough","Central cyanosis, SpO2 below 90%, convulsions or inability to drink","Temperature of 38.6 °C","Fast breathing alone"],"answer":"B","explain":"Danger signs or hypoxaemia indicate severe disease."},{"number":6,"type":"SBA","q":"Which population-level intervention most reduces childhood pneumonia deaths?","options":["Routine pneumococcal conjugate and Hib vaccination within the immunisation programme","Cough syrups","Home isolation of all children","Routine antibiotics for all coughs"],"answer":"A","explain":"Vaccination prevents the most common bacterial causes and is highly cost-effective."},{"number":7,"type":"VSAQ","q":"What does IMCI stand for?","answer":"Integrated Management of Childhood Illness.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"},{"id":"eye1-2-16","paper":"EYE1 Paper 2","module":"RESP","title":"Poorly controlled asthma in a young adult","scenario":"A 26-year-old security guard has had asthma since childhood. He uses his salbutamol inhaler 5 to 6 times a week, wakes\nat night with cough 3 nights a week, and cannot play soccer without wheezing. He is not on a steroid inhaler. He smokes\n5 cigarettes a day and lives in a damp flat with a cat. His chest is clear today. PEF is 70% of predicted.","questions":[{"number":1,"type":"SBA","q":"Which feature best shows that his asthma is poorly controlled?","options":["Reliever use more than twice a week with night waking and activity limitation","A clear chest today","Childhood onset","Normal weight"],"answer":"A","explain":"Frequent symptoms, night waking and reliever use signal poor control."},{"number":2,"type":"SBA","q":"Which mechanism links his triggers to his symptoms?","options":["Airway hyperresponsiveness from chronic eosinophilic inflammation, triggered by allergens and smoke","Alveolar destruction","Bacterial infection","Pulmonary hypertension"],"answer":"A","explain":"Allergens (cat, damp mould) and smoking aggravate eosinophilic airway inflammation and bronchial hyperresponsiveness."},{"number":3,"type":"SBA","q":"Data interpretation\n\nSpirometry             Before bronchodilator                    After bronchodilator\n\nFEV1                   2.4 L (62% predicted)                    3.0 L (77% predicted)\n\nFVC                    4.1 L                                    4.2 L\n\nFEV1/FVC               0.59                                     0.71\n\nWhat is the correct interpretation?","options":["Restrictive pattern","Obstructive pattern with significant bronchodilator reversibility (600 mL, 25%), consistent with asthma","Normal spirometry","Fixed airflow obstruction typical of COPD"],"answer":"B","explain":"A rise in FEV1 of at least 12% and 200 mL after bronchodilator is significant reversibility."},{"number":4,"type":"SBA","q":"What is the most appropriate change to his treatment?","options":["Add regular low-dose inhaled corticosteroid (or ICS-formoterol maintenance and reliever) with a spacer and technique check","Increase salbutamol use","Start oral antibiotics","Start a long-acting β2-agonist alone"],"answer":"A","explain":"Controller therapy with an inhaled steroid treats the underlying inflammation."},{"number":5,"type":"SBA","q":"Why is increasing salbutamol use not appropriate?","options":["SABA relieves symptoms but does not treat inflammation, and overuse is linked to exacerbations and deaths","It is addictive","It causes infection","It lowers blood pressure"],"answer":"A","explain":"Reliance on SABA alone leaves the inflammation untreated."},{"number":6,"type":"SBA","q":"Which non-drug advice is most important?","options":["Stop smoking, reduce allergen and mould exposure, and use a written asthma action plan","Avoid all exercise","Stay indoors always","Use antihistamines daily"],"answer":"A","explain":"Trigger control and self-management reduce exacerbations."},{"number":7,"type":"VSAQ","q":"Which device improves drug delivery from a metered-dose inhaler?","answer":"Spacer.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which inflammatory cell characterises allergic asthmatic airway inflammation?","answer":"Eosinophil.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 2 (educational practice, not an official Wits exam)"}],[{"id":"eye1-3-01","paper":"EYE1 Paper 3","module":"BCMH","title":"Fever, headache and a purpuric rash","scenario":"A 19-year-old first-year student living in a university residence presents with 14 hours of fever, severe headache,\nvomiting and photophobia. She is now drowsy. Temperature 39.6 °C, HR 124/min, BP 92/54 mmHg, RR 26/min, GCS\n12/15, capillary glucose 6.1 mmol/L. She has neck stiffness and a non-blanching purpuric rash over her legs and trunk.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely cause?","options":["Streptococcus pneumoniae","Neisseria meningitidis","Listeria monocytogenes","Herpes simplex virus"],"answer":"B","explain":"A young adult in communal living with meningitis and a purpuric rash points to meningococcus (Gram- negative diplococcus)."},{"number":2,"type":"SBA","q":"Which mechanism best explains the purpuric rash and hypotension?","options":["Endotoxin (LPS) triggering a cytokine storm, endothelial damage and disseminated intravascular coagulation","Type I hypersensitivity to the organism","Direct viral invasion of capillaries","Platelet destruction by autoantibodies"],"answer":"A","explain":"LPS activates macrophages (TNF-α, IL-1, IL-6), causing vascular leak, microthrombi and consumption of platelets and clotting factors."},{"number":3,"type":"SBA","q":"Data interpretation\n\nCSF test                   Result                                    Normal\n\nOpening pressure           32 cmH₂O                                  < 20\n\nWhite cells                2 800/µL (90% neutrophils)                <5\n\nProtein                    3.2 g/L                                   < 0.45\n\nGlucose                    0.8 mmol/L (blood 6.1)                    > 60% of blood glucose\n\nGram stain                 Gram-negative diplococci                  None\n\nWhat is the correct interpretation?","options":["Viral meningitis","Tuberculous meningitis","Bacterial meningitis","Normal CSF"],"answer":"C","explain":"Neutrophils, very high protein, very low glucose and organisms on Gram stain are characteristic of bacterial meningitis."},{"number":4,"type":"SBA","q":"[First-line management] Which is the most appropriate first-line treatment?","options":["Await CSF culture before giving antibiotics","Immediate empirical IV ceftriaxone (with dexamethasone) after blood cultures, without delaying for a lumbar puncture or CT","Oral amoxicillin","IV aciclovir alone"],"answer":"B","explain":"Each hour of delay increases mortality. Blood cultures are taken, then antibiotics are given immediately. Dexamethasone is given with or before the first dose."},{"number":5,"type":"SBA","q":"Which action is most appropriate for her close contacts in the residence?","options":["No action is needed","Isolate them for 6 months","Chemoprophylaxis (e.g. single-dose ciprofloxacin or rifampicin) and advice on symptoms","Intravenous ceftriaxone for all"],"answer":"C","explain":"Close contacts are at increased risk and receive antibiotic prophylaxis. The case is also notified (Category 1)."},{"number":6,"type":"SBA","q":"Which complication best explains refractory shock with extensive purpura in this disease?","options":["Waterhouse-Friderichsen syndrome (bilateral adrenal haemorrhage)","Addisonian crisis from autoimmune adrenalitis","Pulmonary embolism","Anaphylaxis"],"answer":"A","explain":"Fulminant meningococcaemia can cause adrenal haemorrhage and acute adrenal failure."},{"number":7,"type":"VSAQ","q":"What is the name of the sign elicited by resisting passive knee extension with the hip flexed?","answer":"Kernig's sign.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Which bacterial enzymes (targets) are inhibited by β-lactam antibiotics such as ceftriaxone?","answer":"Penicillin-binding proteins.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-02","paper":"EYE1 Paper 3","module":"BCMH","title":"Fever, rash and red eyes in a toddler","scenario":"A 3-year-old boy from a rural area of the Eastern Cape has had 4 days of high fever, cough, runny nose and red eyes.\nYesterday a red blotchy rash appeared behind the ears and has spread to the face and trunk. He has never received any\nvaccinations because the family could not reach the clinic. Temperature 39.2 °C, RR 42/min, SpO2 95%, he is mildly\ndehydrated and thin. Small white spots are seen on the inner cheeks opposite the molars.","questions":[{"number":1,"type":"SBA","q":"What are the white spots on the buccal mucosa called?","options":["Koplik spots","Aphthous ulcers","Oral hairy leukoplakia","Candida plaques"],"answer":"A","explain":"Koplik spots are pathognomonic of measles and appear before the rash."},{"number":2,"type":"SBA","q":"Why does measles predispose to secondary bacterial pneumonia and diarrhoea?","options":["It destroys the skin barrier","The virus infects SLAM (CD150)-bearing lymphocytes and causes transient immune suppression, with mucosal damage","It causes complement deficiency","It causes IgE excess"],"answer":"B","explain":"Measles causes lymphopenia and impaired immune memory for weeks, and damages respiratory and gut epithelium."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                                    Result\n\nMeasles IgM                             Positive\n\nMeasles IgG                             Negative\n\nWhite cell count                        3.1 × 10⁹/L (lymphopenia)\n\nWhat is the correct interpretation?","options":["Past vaccination","Recent or acute measles infection","Chronic infection","Laboratory error"],"answer":"B","explain":"IgM positive with IgG negative indicates acute infection. The lymphopenia fits measles."},{"number":4,"type":"SBA","q":"[First-line management] Which is the most appropriate first-line management?","options":["Vitamin A supplementation with supportive care (fluids or ORS, nutrition, fever control), and treating complications","IV acyclovir","Oral ribavirin for all patients","Broad-spectrum antibiotics for all patients"],"answer":"A","explain":"There is no specific antiviral. Vitamin A reduces mortality and complications in children with measles."},{"number":5,"type":"SBA","q":"Which public-health action is required?","options":["Notify immediately (Category 1), isolate the case and vaccinate susceptible contacts","Wait for laboratory confirmation before any action","Treat all contacts with antibiotics","No action is required"],"answer":"A","explain":"Measles is a Category 1 notifiable condition. Early response limits outbreaks, and vaccination of susceptible contacts within 72 hours may be protective."},{"number":6,"type":"SBA","q":"What level of two-dose measles vaccination coverage is required to maintain herd immunity?","options":["50%","70%","95% or more","100% of one dose"],"answer":"C","explain":"Measles is highly infectious (R0 of 12 to 18), so at least 95% coverage is needed. In SA, vaccine is given at 6 and 12 months."},{"number":7,"type":"VSAQ","q":"Which rare, fatal late neurological complication of measles occurs years later?","answer":"Subacute sclerosing panencephalitis (SSPE).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-03","paper":"EYE1 Paper 3","module":"BCMH","title":"A painless genital sore","scenario":"A 26-year-old man attends a clinic in Hammanskraal with a painless genital sore for 10 days. He has had several partners\nrecently and uses condoms inconsistently. On examination there is a single 1 cm, painless, firm-edged ulcer with a clean\nbase on the penile shaft, and non-tender, rubbery bilateral inguinal lymph nodes. A rapid HIV test is negative today.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely cause?","options":["Herpes simplex virus","Haemophilus ducreyi","Treponema pallidum","Chlamydia trachomatis"],"answer":"C","explain":"A single painless indurated ulcer (chancre) is typical of primary syphilis."},{"number":2,"type":"SBA","q":"Which feature best distinguishes this ulcer from genital herpes?","options":["Presence of an ulcer","Sexual transmission","Painless single indurated ulcer with a clean base, instead of painful clustered vesicles and shallow ulcers","Inguinal lymphadenopathy"],"answer":"C","explain":"Herpes causes painful grouped vesicles that ulcerate, whereas a syphilitic chancre is painless and firm."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                                                       Result\n\nRPR (non-treponemal)                                       Positive, titre 1:32\n\nTPPA (treponemal)                                          Positive\n\nHIV rapid test                                             Negative\n\nWhat is the correct interpretation?","options":["False positive","Past treated syphilis only","Active syphilis infection requiring treatment, with a repeat HIV test in the window period","Genital herpes"],"answer":"C","explain":"A high RPR titre with a positive treponemal test means active disease. HIV testing is repeated because of the window period and shared risk."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line treatment?","options":["A single intramuscular dose of benzathine penicillin","Oral ciprofloxacin","Oral acyclovir alone","Topical antifungal"],"answer":"A","explain":"Benzathine penicillin G is first-line for early syphilis. Syndromic genital ulcer protocols also cover herpes if suspected."},{"number":5,"type":"SBA","q":"Within 24 hours of treatment he develops fever, chills and myalgia. What is the most likely explanation?","options":["Penicillin anaphylaxis","Jarisch-Herxheimer reaction caused by release of spirochaete products from dying organisms","Treatment failure","HIV seroconversion"],"answer":"B","explain":"Mass killing of spirochaetes releases pro-inflammatory lipoproteins. It is self-limited and is not an allergy."},{"number":6,"type":"SBA","q":"Which approach to his partners is most appropriate?","options":["Do nothing as he has no symptoms","Encourage partner notification and presumptive treatment of recent partners, while respecting confidentiality","Notify employers","Withhold his treatment until partners attend"],"answer":"B","explain":"Partner notification breaks the chain of transmission while protecting patient confidentiality."},{"number":7,"type":"VSAQ","q":"Which stage of syphilis is characterised by a chancre?","answer":"Primary.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-04","paper":"EYE1 Paper 3","module":"BCMH","title":"A needle-stick injury","scenario":"A 23-year-old intern sustains a needle-stick injury 40 minutes ago while resiting a drip in a patient who is known to be\nHIV-positive on ART, with a viral load of 82 000 copies/mL. It was a deep puncture with a hollow-bore needle and visible\nblood. The intern's baseline HIV rapid test today is negative. She completed her hepatitis B vaccination series and has a\ndocumented anti-HBs titre of 50 mIU/mL.","questions":[{"number":1,"type":"SBA","q":"Which factor most increases her risk of HIV transmission?","options":["Superficial scratch","Deep injury with a hollow-bore needle and visible blood from a source with a high viral load","Source patient on ART","A solid suture needle"],"answer":"B","explain":"Risk rises with deep injury, hollow-bore needles, visible blood and a high source viral load."},{"number":2,"type":"SBA","q":"What is the most appropriate immediate first aid?","options":["Squeeze the site hard and apply bleach","Scrub vigorously","Let it bleed freely and wash with soap and running water","Suck the wound"],"answer":"C","explain":"Do not scrub, squeeze or use bleach, which damage tissue. Wash with soap and water."},{"number":3,"type":"SBA","q":"[First-line management] Which is the first-line HIV post-exposure prophylaxis (PEP)?","options":["Tenofovir, lamivudine and dolutegravir (TLD) for 28 days, started as soon as possible","Single-dose nevirapine","Isoniazid for 6 months","Cotrimoxazole"],"answer":"A","explain":"TLD is the recommended PEP regimen. It should be started ideally within 2 hours and no later than 72 hours."},{"number":4,"type":"SBA","q":"Data interpretation\n\nTime                                                    HIV test result\n\nBaseline (day 0)                                        Negative\n\n6 weeks                                                 Negative\n\n3 months                                                Negative\n\nWhat is the correct interpretation?","options":["Seroconversion","HIV infection excluded, because tests remain negative beyond the window period","Indeterminate","Test must be repeated annually"],"answer":"B","explain":"Negative tests at 3 months, beyond the window period, exclude infection from this exposure."},{"number":5,"type":"SBA","q":"What does her anti-HBs titre of 50 mIU/mL (above 10) mean for hepatitis B?","options":["She needs hepatitis B immunoglobulin urgently","She is protected and needs no further hepatitis B treatment","She has chronic hepatitis B","She needs a vaccine series restart"],"answer":"B","explain":"An anti-HBs titre of at least 10 mIU/mL indicates immunity from vaccination."},{"number":6,"type":"SBA","q":"Which professional response is most appropriate?","options":["Say nothing, as the patient may be upset","Report the exposure immediately through occupational health channels, with confidential counselling and follow-up","Delay reporting until test results are available","Tell the patient's family"],"answer":"B","explain":"Prompt reporting enables PEP and protects colleagues and patients. Confidentiality applies to both the intern and the source patient."},{"number":7,"type":"VSAQ","q":"Which acronym describes HIV medication taken before exposure by people at risk?","answer":"PrEP.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the maximum number of hours after exposure that PEP can still be started?","answer":"72 hours.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-05","paper":"EYE1 Paper 3","module":"BCMH","title":"Flushing and low blood pressure during an infusion","scenario":"A 60-year-old man in a surgical ward receives his first dose of IV vancomycin for an MRSA wound infection, infused\nrapidly over 20 minutes. Fifteen minutes in, he develops intense itching and flushing of the face, neck and upper trunk\nwith blotchy erythema. BP 102/64 mmHg (baseline 128/76), HR 104/min, SpO2 97%. There is no wheeze, stridor or lip\nswelling. He has never received vancomycin before and has no known allergies.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains this reaction on first exposure?","options":["Direct non-IgE-mediated mast-cell degranulation","Type II antibody-mediated cytotoxicity","Type IV delayed hypersensitivity","Immune-complex deposition"],"answer":"A","explain":"This is an anaphylactoid reaction: mast cells are triggered directly by the drug (and rate of infusion) without prior sensitisation."},{"number":2,"type":"SBA","q":"Which feature favours an anaphylactoid reaction over IgE-mediated anaphylaxis?","options":["Itching","Hypotension","Occurrence on first exposure, related to the rate of infusion","Flushing"],"answer":"C","explain":"IgE-mediated allergy requires prior sensitisation. Anaphylactoid reactions can occur on first exposure and are often rate-dependent."},{"number":3,"type":"SBA","q":"[First-line management] What is the most appropriate first-line management of this reaction?","options":["Continue the infusion at the same rate","Stop the infusion, assess airway, breathing and circulation, give an antihistamine and restart more slowly once settled","Give oral steroids and discharge","Permanently label him allergic to all antibiotics"],"answer":"B","explain":"Pausing the infusion, giving an antihistamine and re-challenging at a slower rate is standard. IM adrenaline is given if there is airway, breathing or circulatory compromise."},{"number":4,"type":"SBA","q":"Data interpretation\n\nAttempt                                       Infusion duration      Reaction\n\n1                                             20 minutes             Flushing, itching, BP 102/64\n\n2 (after antihistamine, 3 hours later)        2 hours                None\n\nWhat does this show?","options":["A true IgE allergy","A rate-dependent infusion reaction, supporting non-IgE mast-cell activation","Drug resistance","Anaphylaxis requiring permanent avoidance"],"answer":"B","explain":"Reaction on fast infusion, absent on slow infusion, indicates a rate-related, non-IgE mechanism."},{"number":5,"type":"SBA","q":"If he had developed wheeze and a BP of 70/40 mmHg, what would be the correct approach?","options":["Treat as anaphylaxis with IM adrenaline, as the mediators and clinical picture are the same","Observe only, because it is not a true allergy","Give oral antihistamine only","Give IV steroids first"],"answer":"A","explain":"Severe anaphylactoid reactions are clinically indistinguishable from anaphylaxis and are treated the same way."},{"number":6,"type":"SBA","q":"Which documentation is most appropriate?","options":["Record it as vancomycin allergy for life","Record it as an infusion reaction with advice on slow infusion, so he is not wrongly labelled allergic","Do not record anything","Record only in verbal handover"],"answer":"B","explain":"Accurate labelling guides safe future use and avoids unnecessary use of less effective drugs (patient safety)."},{"number":7,"type":"VSAQ","q":"What is the common name for this vancomycin infusion reaction?","answer":"Red man syndrome.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-06","paper":"EYE1 Paper 3","module":"CVS","title":"Chest tightness on walking uphill","scenario":"A 59-year-old man who smokes and has hypertension reports 3 months of central chest tightness when climbing two\nflights of stairs or walking uphill. It lasts 3 to 5 minutes and is relieved by rest. He has never had pain at rest. Examination\nis normal. BP 146/88 mmHg. Resting ECG is normal. LDL cholesterol is 4.6 mmol/L.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains his symptoms?","options":["Plaque rupture with complete occlusion","Fixed atherosclerotic coronary narrowing causing demand ischaemia when myocardial oxygen need rises","Aortic dissection","Pericardial inflammation"],"answer":"B","explain":"A fixed stenosis cannot increase flow with exertion, so ischaemia occurs on demand without acute thrombosis."},{"number":2,"type":"SBA","q":"Which feature distinguishes stable from unstable angina?","options":["Chest pain location","Predictable exertional pattern, relieved by rest, with no recent change","Radiation to the arm","Sweating"],"answer":"B","explain":"Unstable angina occurs at rest, with increasing frequency or at lower thresholds."},{"number":3,"type":"SBA","q":"Data interpretation\nExercise stress ECG: \"At 6 minutes he develops chest tightness with 1.8 mm horizontal ST depression in V4 to V6. Changes\nresolve 4 minutes after stopping.\"\n\nWhat is the interpretation?","options":["Normal test","Positive test indicating inducible myocardial ischaemia, so refer for further evaluation","Pericarditis","Pulmonary disease"],"answer":"B","explain":"Reproducible symptoms with ST depression indicate inducible ischaemia. Further risk stratification (e.g. angiography) is needed."},{"number":4,"type":"SBA","q":"[First-line management] Which drug is first-line for acute relief of an attack?","options":["Oral paracetamol","Sublingual glyceryl trinitrate (GTN)","Oral aspirin","IV adenosine"],"answer":"B","explain":"Sublingual GTN relieves an attack. Long-term prevention uses aspirin, a statin and a β-blocker or calcium- channel blocker, with risk-factor control."},{"number":5,"type":"SBA","q":"How does GTN relieve angina?","options":["It increases heart rate","It causes venodilation, reducing preload and myocardial oxygen demand, and dilates coronary vessels","It blocks calcium channels","It inhibits platelets"],"answer":"B","explain":"Nitrates release nitric oxide, increasing cGMP and relaxing smooth muscle."},{"number":6,"type":"SBA","q":"Which drug interaction makes GTN dangerous?","options":["Paracetamol","Phosphodiesterase-5 inhibitors (e.g. sildenafil), causing profound hypotension","Metformin","Antihistamines"],"answer":"B","explain":"Both drugs increase cGMP, so combined use can cause severe hypotension."},{"number":7,"type":"VSAQ","q":"What is the name of angina caused by coronary vasospasm at rest?","answer":"Prinzmetal (variant) angina.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-07","paper":"EYE1 Paper 3","module":"CVS","title":"Crushing chest pain with a slow pulse","scenario":"A 55-year-old man presents with 2 hours of crushing central chest pain, nausea, vomiting, sweating and dizziness. HR\n38/min, BP 88/54 mmHg, RR 22/min, SpO2 95%. He is cool and clammy. His lungs are clear and JVP is not raised. ECG: ST\nelevation in II, III and aVF with ST depression in I and aVL. P waves are unrelated to the QRS complexes, with a\nventricular rate of 38/min.","questions":[{"number":1,"type":"SBA","q":"Which coronary artery is most likely occluded?","options":["Left anterior descending artery","Right coronary artery","Left main stem","Diagonal branch"],"answer":"B","explain":"Inferior ST elevation points to the RCA in most people (right-dominant circulation)."},{"number":2,"type":"SBA","q":"Which mechanism best explains his bradycardia?","options":["Ischaemia of the AV node (supplied by the RCA) causing AV block, plus vagal reflex activation","Left ventricular hypertrophy","Hypothyroidism","Sinus tachycardia"],"answer":"A","explain":"The AV nodal artery usually arises from the RCA, and inferior MI also triggers the Bezold-Jarisch vagal reflex."},{"number":3,"type":"SBA","q":"Data interpretation\nECG report: \"ST elevation II, III, aVF. P waves regular at 80/min. QRS regular at 38/min. No relationship between P waves\nand QRS.\"\n\nWhat is the correct interpretation?","options":["Anterior STEMI with sinus rhythm","Inferior STEMI with complete (third-degree) heart block","Atrial fibrillation","First-degree heart block"],"answer":"B","explain":"Independent atrial and ventricular activity indicates complete heart block."},{"number":4,"type":"SBA","q":"[First-line management] The nearest PCI centre is 4 hours away. What is the first-line reperfusion strategy?","options":["Wait for transfer without treatment","Fibrinolysis (e.g. streptokinase) within 30 minutes of arrival, with antiplatelet therapy, then transfer","Oral anticoagulation only","Elective angiography next week"],"answer":"B","explain":"If primary PCI cannot be delivered within about 120 minutes, fibrinolysis is the first-line reperfusion option."},{"number":5,"type":"SBA","q":"Which treatment is appropriate for his symptomatic bradycardia?","options":["IV atropine, with transcutaneous pacing if there is no response","IV verapamil","IV metoprolol","Observation only"],"answer":"A","explain":"Atropine blocks vagal tone. Pacing is used if heart block persists."},{"number":6,"type":"SBA","q":"Why should nitrates and large doses of morphine be avoided in his situation?","options":["They cause bradycardia only","A right ventricular infarct may be present, making him preload-dependent, so venodilation can cause profound hypotension","They are ineffective","They cause clotting"],"answer":"B","explain":"Inferior MI often involves the RV. The failing RV depends on adequate preload."},{"number":7,"type":"VSAQ","q":"Which ECG lead placement helps detect right ventricular infarction?","answer":"Right-sided leads (V4R).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Aspirin irreversibly inhibits which enzyme in platelets?","answer":"Cyclooxygenase (COX-1).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-08","paper":"EYE1 Paper 3","module":"CVS","title":"A preterm baby with a machinery murmur","scenario":"A 6-day-old boy was born at 29 weeks with a birth weight of 1.1 kg and is on nasal CPAP. His oxygen requirement is\nrising and he has apnoeic episodes. He has bounding pulses, a hyperdynamic precordium and a continuous murmur at\nthe left infraclavicular area. BP 70/25 mmHg. CXR shows cardiomegaly and pulmonary plethora.","questions":[{"number":1,"type":"SBA","q":"Why does this structure remain open in preterm infants?","options":["Immature ductal tissue is less responsive to oxygen-induced constriction, with high circulating prostaglandins","A genetic fusion defect","High pulmonary pressure after birth","Maternal antibodies"],"answer":"A","explain":"Preterm ductal smooth muscle is less sensitive to oxygen and more sensitive to prostaglandin E2."},{"number":2,"type":"SBA","q":"Which mechanism best explains the wide pulse pressure and bounding pulses?","options":["Aortic runoff into the pulmonary artery during diastole lowers diastolic pressure","Aortic stenosis","Mitral regurgitation","Pericardial effusion"],"answer":"A","explain":"Continuous left-to-right flow drains the aorta in diastole, so diastolic pressure falls."},{"number":3,"type":"SBA","q":"Data interpretation\nEchocardiogram report: \"3.5 mm PDA with left-to-right flow. Left atrium to aortic root ratio 1.7 (normal < 1.4). Diastolic\nflow reversal in the descending aorta.\"\n\nWhat does this indicate?","options":["Insignificant ductus","Haemodynamically significant PDA with left heart volume overload","Tetralogy of Fallot","Normal study"],"answer":"B","explain":"A large LA, a high LA:Ao ratio and diastolic flow reversal show a significant shunt."},{"number":4,"type":"SBA","q":"[First-line management] Which is first-line medical treatment to close the ductus?","options":["Prostaglandin E1 infusion","Indomethacin or ibuprofen (a prostaglandin synthesis inhibitor)","Digoxin","Antibiotics"],"answer":"B","explain":"NSAIDs inhibit COX, reducing prostaglandin levels and promoting ductal closure. Paracetamol is an alternative."},{"number":5,"type":"SBA","q":"Which mechanism explains how the drug closes the ductus?","options":["It inhibits cyclooxygenase, lowering prostaglandin-mediated ductal relaxation","It blocks calcium channels","It stimulates the ductal muscle directly","It inhibits thrombin"],"answer":"A","explain":"Lowering prostaglandin levels allows the ductus to constrict."},{"number":6,"type":"SBA","q":"Which adverse effect must be monitored during treatment?","options":["Hair loss","Reduced urine output and renal impairment (also risk of necrotising enterocolitis)","Cataracts","Cough"],"answer":"B","explain":"NSAIDs reduce renal prostaglandins, so monitor urine output and creatinine."},{"number":7,"type":"VSAQ","q":"What does the ductus arteriosus become after closure?","answer":"Ligamentum arteriosum.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-09","paper":"EYE1 Paper 3","module":"CVS","title":"Collapse in a shopping mall","scenario":"A 63-year-old man collapses in a shopping mall. A bystander finds him unresponsive and not breathing normally, with no\npulse. Paramedics arrive 6 minutes later with a defibrillator.","questions":[{"number":1,"type":"SBA","q":"What should the bystander do first?","options":["Check blood glucose","Call for emergency help and start continuous chest compressions","Give oral water","Move him to a bed"],"answer":"B","explain":"Early recognition, calling for help and immediate high-quality CPR is the start of the chain of survival."},{"number":2,"type":"SBA","q":"Which mechanism underlies a shockable collapse rhythm such as ventricular fibrillation?","options":["Complete absence of electrical activity","Chaotic, uncoordinated ventricular depolarisation with no effective cardiac output","Slow regular ventricular rhythm","Electromechanical dissociation"],"answer":"B","explain":"Multiple re-entrant wavelets cause quivering of the ventricles instead of contraction."},{"number":3,"type":"SBA","q":"Data interpretation\nRhythm strip: \"Chaotic, irregular undulations of varying amplitude. No identifiable P waves, QRS complexes or T waves.\"\n\nWhat is the rhythm and its implication?","options":["Asystole: do not shock","Ventricular fibrillation: shockable rhythm","Sinus rhythm","Atrial fibrillation: rate control"],"answer":"B","explain":"A chaotic irregular tracing with no recognisable complexes is VF."},{"number":4,"type":"SBA","q":"[First-line management] What is the first-line treatment of this rhythm?","options":["IV adrenaline alone","Immediate defibrillation (unsynchronised shock) together with CPR","Synchronised cardioversion","IV atropine"],"answer":"B","explain":"Early defibrillation is the most important determinant of survival in VF/pulseless VT."},{"number":5,"type":"SBA","q":"What should be done immediately after delivering the first shock?","options":["Check the pulse for 30 seconds","Resume chest compressions at once for 2 minutes before reassessing the rhythm","Stop resuscitation","Give a second shock immediately"],"answer":"B","explain":"Minimising interruptions to compressions improves coronary and cerebral perfusion."},{"number":6,"type":"SBA","q":"Which drug is given during the resuscitation of this shockable rhythm?","options":["IV adrenaline 1 mg every 3 to 5 minutes (after the second shock), with amiodarone after the third shock","Oral aspirin only","IV furosemide","IV insulin"],"answer":"A","explain":"Adrenaline increases coronary perfusion pressure. Amiodarone is used for shock-refractory VF."},{"number":7,"type":"VSAQ","q":"What is the acronym for the device that gives rhythm analysis and shock instructions to lay rescuers?","answer":"AED (automated external defibrillator).","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the recommended chest compression rate per minute?","answer":"100 to 120.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-10","paper":"EYE1 Paper 3","module":"CVS","title":"Fever and joint pain after a sore throat","scenario":"An 11-year-old girl from Mthatha presents 2 weeks after an untreated sore throat with fever of 38.8 °C, migrating pain\nand swelling of the knees and ankles, and a new apical pansystolic murmur. There is a faint pink ring-shaped rash on the\ntrunk.","questions":[{"number":1,"type":"SBA","q":"Which organism triggers this condition?","options":["Staphylococcus aureus","Group A β-haemolytic Streptococcus (Streptococcus pyogenes)","Streptococcus pneumoniae","Neisseria meningitidis"],"answer":"B","explain":"Acute rheumatic fever follows untreated group A streptococcal pharyngitis."},{"number":2,"type":"SBA","q":"Which of her features are major Jones criteria?","options":["Fever and raised ESR","Migratory polyarthritis and carditis","Raised ASO titre","Prolonged PR interval"],"answer":"B","explain":"Major criteria include carditis, arthritis, chorea, erythema marginatum and subcutaneous nodules. Fever, ESR and PR prolongation are minor criteria."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                                          Result\n\nASO titre                                     800 IU/mL (raised)\n\nESR / CRP                                     85 mm/h / 90 mg/L\n\nECG                                           PR interval 220 ms\n\nEchocardiogram                                Mitral regurgitation\n\nWhat is the correct interpretation?","options":["Does not meet criteria","Meets Jones criteria: two major criteria with evidence of preceding streptococcal infection, confirming acute rheumatic fever","Viral arthritis","Septic arthritis"],"answer":"B","explain":"Two major criteria plus evidence of recent group A streptococcal infection make the diagnosis."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line treatment?","options":["Intramuscular benzathine penicillin to eradicate the streptococcus, with aspirin or an NSAID for arthritis and rest, treating heart failure if present","Antibiotics only for one day","Warfarin","Methotrexate"],"answer":"A","explain":"Penicillin eradicates the organism, and anti-inflammatories control joint symptoms. Steroids are reserved for severe carditis."},{"number":5,"type":"SBA","q":"Which long-term preventive strategy is required?","options":["Secondary prophylaxis with regular benzathine penicillin injections for many years","A single dose of oral penicillin","No prophylaxis","Annual influenza vaccine only"],"answer":"A","explain":"Prophylaxis every 3 to 4 weeks prevents recurrences and progression to rheumatic heart disease, for at least 10 years or until age 21 (longer with carditis)."},{"number":6,"type":"SBA","q":"Which population-level intervention best reduces acute rheumatic fever?","options":["Prompt treatment of streptococcal sore throats and improving housing and overcrowding","Routine steroids","Daily aspirin for all children","Closing schools"],"answer":"A","explain":"Rheumatic fever is a disease of poverty and overcrowding, and primary prevention is early treatment of strep throat."},{"number":7,"type":"VSAQ","q":"Which neurological manifestation of rheumatic fever causes involuntary jerky movements?","answer":"Sydenham chorea.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-11","paper":"EYE1 Paper 3","module":"CVS","title":"A lethargic toddler with diarrhoea","scenario":"A 14-month-old girl in Gugulethu has had 3 days of profuse watery diarrhoea and vomiting. She is lethargic with sunken\neyes, a sunken fontanelle, a dry mouth and no tears. Skin pinch returns very slowly. Her hands and feet are cold,\ncapillary refill is 5 seconds and the pulse is weak and fast at 180/min. RR 44/min. Weight 8.5 kg (9.5 kg two weeks ago).","questions":[{"number":1,"type":"SBA","q":"Which classification best describes her condition?","options":["No dehydration","Some dehydration","Severe dehydration with hypovolaemic shock","Septic shock"],"answer":"C","explain":"Lethargy, poor perfusion, slow skin pinch and sunken eyes indicate severe dehydration with shock."},{"number":2,"type":"SBA","q":"Which mechanism explains her cold peripheries and weak pulse?","options":["Reduced circulating volume lowers preload and stroke volume, causing compensatory tachycardia and peripheral vasoconstriction","Primary heart failure","Vasodilation from sepsis","Arterial thrombosis"],"answer":"A","explain":"Fluid loss reduces venous return, so the body shifts blood to the core."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                                Result                               Normal\n\npH                                  7.18                                 7.35 to 7.45\n\nBicarbonate                         8 mmol/L                             22 to 26\n\nPotassium                           3.0 mmol/L                           3.5 to 5.0\n\nGlucose                             2.9 mmol/L                           3.5 to 5.5\n\nWhat is the correct interpretation?","options":["Respiratory acidosis","Metabolic acidosis with hypokalaemia and hypoglycaemia requiring urgent correction","Normal","Respiratory alkalosis"],"answer":"B","explain":"Stool bicarbonate loss and lactic acidosis cause metabolic acidosis. Hypoglycaemia must be corrected urgently."},{"number":4,"type":"SBA","q":"[First-line management] What is the first-line resuscitation?","options":["Oral rehydration solution alone","Rapid IV bolus of isotonic crystalloid (Ringer's lactate or 0.9% saline), reassessing after each bolus, and correcting glucose","Antibiotics","Antidiarrhoeal drug"],"answer":"B","explain":"Shock needs rapid IV volume replacement. ORS is for non-shocked children."},{"number":5,"type":"SBA","q":"Once she has stabilised, which treatment should be continued?","options":["Oral rehydration solution plus zinc supplementation, with continued feeding","Fasting for 24 hours","Loperamide","Routine antibiotics"],"answer":"A","explain":"ORS and zinc (10 to 14 days) reduce severity and recurrence. Feeding should continue."},{"number":6,"type":"SBA","q":"In which situation are antibiotics indicated in childhood diarrhoea?","options":["All watery diarrhoea","Bloody diarrhoea (dysentery, e.g. Shigella) or suspected cholera with severe dehydration","Mild diarrhoea","Vomiting alone"],"answer":"B","explain":"Most gastroenteritis is viral, and antibiotics are reserved for dysentery and cholera."},{"number":7,"type":"VSAQ","q":"Which virus is the commonest cause of severe gastroenteritis in infants?","answer":"Rotavirus.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"If IV access cannot be obtained quickly in a shocked child, which alternative route is used?","answer":"Intraosseous.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-12","paper":"EYE1 Paper 3","module":"RESP","title":"Barking cough and noisy breathing","scenario":"A 2-year-old girl has had 2 days of runny nose followed by a barking cough, hoarse voice and noisy breathing that\nworsens at night. Temperature 38.1 °C. She has inspiratory stridor at rest, mild subcostal and suprasternal recession and\nSpO2 of 96%. She is alert and drinking.","questions":[{"number":1,"type":"SBA","q":"Which organism is the most likely cause?","options":["Parainfluenza virus","Haemophilus influenzae type b","Streptococcus pneumoniae","Mycobacterium tuberculosis"],"answer":"A","explain":"Parainfluenza viruses cause most cases of croup (laryngotracheobronchitis)."},{"number":2,"type":"SBA","q":"Which mechanism explains the stridor?","options":["Subglottic inflammation and oedema narrowing the airway at the cricoid level, causing turbulent flow","Bronchospasm in small airways","Alveolar consolidation","Foreign body in the oesophagus"],"answer":"A","explain":"The subglottis is the narrowest part of the child's airway, so small swelling greatly increases resistance."},{"number":3,"type":"SBA","q":"Data interpretation\nNeck X-ray (AP): \"Symmetrical subglottic narrowing (steeple sign). Epiglottis normal.\"\n\nWhat is the interpretation?","options":["Epiglottitis","Croup","Foreign body","Retropharyngeal abscess"],"answer":"B","explain":"The steeple sign confirms subglottic narrowing. Imaging is rarely needed and should never delay treatment."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line treatment?","options":["Antibiotics","A single dose of dexamethasone, with nebulised adrenaline when there is stridor at rest or distress","Oral antihistamine","Cough suppressant"],"answer":"B","explain":"Corticosteroids reduce airway oedema, and nebulised adrenaline gives rapid temporary relief. Keep the child calm."},{"number":5,"type":"SBA","q":"Which finding indicates impending airway obstruction and requires urgent escalation?","options":["Barking cough","Drowsiness, cyanosis, drooling, or reduced air entry with tiring","Mild fever","Hoarse voice"],"answer":"B","explain":"Exhaustion and cyanosis show failing respiratory effort."},{"number":6,"type":"SBA","q":"Which feature would suggest epiglottitis rather than croup?","options":["Barking cough","Toxic child with high fever, drooling, tripod posture and no cough","Runny nose","Night-time worsening"],"answer":"B","explain":"Epiglottitis (Hib) is a toxic, drooling child, and throat examination should be avoided."},{"number":7,"type":"VSAQ","q":"Which vaccine has made epiglottitis rare?","answer":"Hib vaccine.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-13","paper":"EYE1 Paper 3","module":"RESP","title":"A stab wound to the chest","scenario":"A 28-year-old man is stabbed in the right chest 15 minutes ago and is brought to casualty in Hillbrow. He is severely\ndyspnoeic and agitated. RR 40/min, HR 135/min, BP 78/50 mmHg, SpO2 82% on 15 L/min oxygen. The trachea is\ndeviated to the left, the neck veins are distended, breath sounds are absent on the right and percussion is\nhyperresonant on the right. Subcutaneous emphysema is present.","questions":[{"number":1,"type":"SBA","q":"Which mechanism explains his deterioration?","options":["A one-way valve lets air enter the pleural space but not escape, raising pressure, collapsing the lung and shifting the mediastinum","Massive haemothorax only","Pulmonary oedema","Pulmonary embolism"],"answer":"A","explain":"Rising intrathoracic pressure kinks the great veins, reducing venous return and cardiac output."},{"number":2,"type":"SBA","q":"Which type of shock is present?","options":["Hypovolaemic","Cardiogenic","Obstructive","Neurogenic"],"answer":"C","explain":"Reduced venous return from mediastinal shift and raised pressure is obstructive shock."},{"number":3,"type":"SBA","q":"Data interpretation\n\nFinding                                              Result\n\nTrachea                                              Deviated to the left\n\nRight breath sounds                                  Absent\n\nRight percussion                                     Hyperresonant\n\nJVP                                                  Raised\n\nBP / SpO2                                            78/50 mmHg / 82%\n\nWhat is the correct interpretation and action?","options":["Wait for a chest X-ray before treatment","Tension pneumothorax: a clinical diagnosis requiring immediate decompression","Haemothorax: await blood results","Pneumonia"],"answer":"B","explain":"Tension pneumothorax is diagnosed clinically and treated before imaging."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line life-saving intervention?","options":["Immediate needle decompression of the affected side, followed by a chest drain","Intubation first","IV antibiotics","Observation"],"answer":"A","explain":"A large-bore needle is placed into the pleural space (2nd intercostal space mid-clavicular line or 5th intercostal space anterior axillary line)."},{"number":5,"type":"SBA","q":"Which is the definitive treatment after decompression?","options":["Intercostal chest drain with underwater seal","Repeated needle decompression only","Chest physiotherapy","Bronchodilators"],"answer":"A","explain":"A chest drain re-expands the lung and prevents re-accumulation."},{"number":6,"type":"SBA","q":"If instead he had an open \"sucking\" chest wound, what is the first-line dressing?","options":["A fully occlusive airtight dressing","A three-sided occlusive dressing that acts as a flutter valve","No dressing","Packing the wound tightly with gauze"],"answer":"B","explain":"A three-sided dressing allows air to escape but not enter, avoiding tension pneumothorax."},{"number":7,"type":"VSAQ","q":"Which structured approach guides initial trauma assessment (acronym)?","answer":"ABCDE.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"Along which border of the rib is the needle or drain inserted to avoid the neurovascular bundle?","answer":"Upper border.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-14","paper":"EYE1 Paper 3","module":"RESP","title":"Recurrent chest infections and greasy stools","scenario":"A 4-year-old boy in Johannesburg has had recurrent chest infections with a productive cough since infancy. He has bulky,\nfoul-smelling, greasy stools and poor weight gain (below the 3rd centile) despite a good appetite. His mother says his\nskin tastes salty. He has finger clubbing and bilateral coarse crackles. Previous sputum grew Staphylococcus aureus and\nPseudomonas aeruginosa.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains his condition?","options":["Defective CFTR chloride channel causing thick, dehydrated secretions that obstruct airways and pancreatic ducts","Immotile cilia","Alpha-1 antitrypsin deficiency","Antibody deficiency"],"answer":"A","explain":"Defective chloride and water transport produces viscous mucus. Inheritance is autosomal recessive."},{"number":2,"type":"SBA","q":"Why does he have steatorrhoea and poor weight gain?","options":["Gluten sensitivity","Pancreatic duct obstruction causing exocrine insufficiency and fat malabsorption","Lactose intolerance","Giardia infection"],"answer":"B","explain":"Lack of pancreatic lipase prevents fat digestion, giving greasy stools and failure to thrive."},{"number":3,"type":"SBA","q":"Data interpretation\n\nTest                          Result                  Reference\n\nSweat chloride                82 mmol/L               < 30 normal, ≥ 60 diagnostic\n\nWhat does this show?","options":["Normal","Diagnostic of cystic fibrosis","Borderline result","Dehydration"],"answer":"B","explain":"A sweat chloride of 60 mmol/L or more on repeated testing confirms CF."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line treatment for his malabsorption and poor growth?","options":["Pancreatic enzyme replacement with every meal, a high-energy diet and fat-soluble vitamin supplements","Low-fat diet only","Antibiotics","Gluten-free diet"],"answer":"A","explain":"Enzymes taken with food allow fat absorption, and fat-soluble vitamins (A, D, E, K) are supplemented."},{"number":5,"type":"SBA","q":"Which is the cornerstone of respiratory management?","options":["Daily airway clearance (chest physiotherapy) with prompt antibiotics for exacerbations","Cough suppressants","Long-term oral steroids","Bed rest"],"answer":"A","explain":"Clearing thick secretions limits infection and lung damage. Hypertonic saline and DNase may help."},{"number":6,"type":"SBA","q":"What is the recurrence risk for each pregnancy of his carrier parents?","options":["0%","25%","50%","100%"],"answer":"B","explain":"Autosomal recessive inheritance gives a 25% chance of an affected child with each pregnancy."},{"number":7,"type":"VSAQ","q":"What is the commonest CFTR mutation?","answer":"ΔF508 (F508del).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-15","paper":"EYE1 Paper 3","module":"RESP","title":"Falling asleep at the wheel","scenario":"A 48-year-old male taxi driver with a BMI of 38 and a neck circumference of 46 cm presents with loud snoring, witnessed\npauses in breathing, unrefreshing sleep and morning headaches. He nearly crashed after falling asleep at traffic lights.\nBP 158/96 mmHg despite two antihypertensives. Epworth Sleepiness Score is 17 out of 24.","questions":[{"number":1,"type":"SBA","q":"Which mechanism best explains his symptoms?","options":["Repetitive collapse of the upper airway during sleep, with intermittent hypoxia and arousals","Central brain tumour","Narcolepsy","Asthma"],"answer":"A","explain":"Reduced pharyngeal muscle tone with fat deposition causes airway collapse, hypoxia and fragmented sleep."},{"number":2,"type":"SBA","q":"Which mechanism contributes to his resistant hypertension?","options":["Excess salt intake only","Sympathetic activation from repeated hypoxia and arousals","Hypothyroidism","Renal artery embolism"],"answer":"B","explain":"Repetitive hypoxia and arousals increase sympathetic output and blood pressure."},{"number":3,"type":"SBA","q":"Data interpretation\n\nPolysomnography                                                      Result\n\nApnoea-hypopnoea index (AHI)                                         42 events/hour\n\nLowest SpO2                                                          71%\n\nClassification: mild 5 to 15, moderate 15 to 30, severe over 30 events/hour. What is the diagnosis?","options":["Normal sleep","Mild OSA","Moderate OSA","Severe OSA"],"answer":"D","explain":"An AHI of 42 is severe obstructive sleep apnoea."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line treatment?","options":["Sleeping tablets","Continuous positive airway pressure (CPAP), with weight loss and avoidance of alcohol and sedatives","Oral steroids","Antibiotics"],"answer":"B","explain":"CPAP splints the airway open during sleep and is first-line for moderate to severe OSA."},{"number":5,"type":"SBA","q":"Which advice is most important for his safety?","options":["Drive more slowly","Avoid driving while sleepy until treated, and counsel on occupational risk","Drink coffee while driving","Take sedatives at night"],"answer":"B","explain":"Untreated OSA with sleepiness greatly increases road crash risk (public safety and professionalism)."},{"number":6,"type":"SBA","q":"Which complications are associated with untreated disease?","options":["Hypertension, atrial fibrillation, pulmonary hypertension and stroke","Cataracts only","Osteoporosis only","None"],"answer":"A","explain":"Repeated hypoxia damages the cardiovascular system, leading to pulmonary hypertension, arrhythmia and stroke."},{"number":7,"type":"VSAQ","q":"Which questionnaire is used to assess daytime sleepiness?","answer":"Epworth Sleepiness Scale.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the acronym for the number of apnoeas and hypopnoeas per hour of sleep?","answer":"AHI (apnoea-hypopnoea index).","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"},{"id":"eye1-3-16","paper":"EYE1 Paper 3","module":"RESP","title":"A young child living with a TB patient","scenario":"A 3-year-old girl is brought to a clinic in Khayelitsha by her mother, who was diagnosed with pulmonary TB 2 weeks ago\n(Xpert positive, rifampicin-susceptible) and is on RHZE. The child shares a bed with her mother. She is well: afebrile, no\ncough, good weight and a normal examination. She received BCG at birth. Her HIV test is negative.","questions":[{"number":1,"type":"SBA","q":"Why are young children at higher risk of severe forms of TB after exposure?","options":["They have more lung tissue","Immature cell-mediated immunity leads to rapid progression to disease, including miliary and meningeal TB","They have stronger antibody responses","They are rarely exposed"],"answer":"B","explain":"Young children progress quickly from infection to disease, often with disseminated forms."},{"number":2,"type":"SBA","q":"What is the first step in evaluating this child?","options":["Immediate starting of RHZE","Symptom screening (cough, fever, weight loss or poor growth, lethargy), examination, and chest X-ray where indicated","No evaluation","BCG revaccination"],"answer":"B","explain":"Household contacts under 5 are screened first to exclude active TB."},{"number":3,"type":"SBA","q":"Data interpretation\n\nScreen                                                                             Result\n\nCough more than 2 weeks                                                            No\n\nFever                                                                              No\n\nWeight loss or failure to thrive                                                   No\n\nLethargy                                                                           No\n\nChest X-ray                                                                        Normal\n\nWhat is the interpretation?","options":["Active TB","Screen negative: asymptomatic contact with no evidence of active TB, but at risk of latent infection and progression","TB meningitis","Drug-resistant TB"],"answer":"B","explain":"She has no symptoms or radiological evidence of disease, but is a high-risk contact."},{"number":4,"type":"SBA","q":"[First-line management] Which is the first-line management for this asymptomatic child?","options":["No treatment and review in a year","TB preventive therapy (e.g. 6 months of isoniazid)","Full RHZE treatment","BCG revaccination"],"answer":"B","explain":"Children under 5 in contact with infectious TB are given preventive therapy once active TB is excluded."},{"number":5,"type":"SBA","q":"Why must active TB be excluded before starting preventive therapy?","options":["Preventive drugs are toxic","Single-drug treatment of active disease would select for drug resistance","It saves cost","Active TB cannot occur in children"],"answer":"B","explain":"Giving one drug to someone with active, high-bacillary-load disease promotes resistance."},{"number":6,"type":"SBA","q":"What protection does BCG provide?","options":["Complete protection against infection","Protection against severe disseminated forms (miliary TB and TB meningitis) in young children","Treatment of latent TB","No effect"],"answer":"B","explain":"BCG reduces severe childhood forms but does not reliably prevent infection or adult pulmonary TB."},{"number":7,"type":"VSAQ","q":"What is infection with viable TB bacilli without disease called?","answer":"Latent TB infection.","explain":"The expected short answer from the source paper is shown above."},{"number":8,"type":"VSAQ","q":"What is the process of identifying and screening people exposed to an infectious case called?","answer":"Contact tracing.","explain":"The expected short answer from the source paper is shown above."}],"source":"Uploaded GEMP1 EYE1 Practice Paper 3 (educational practice, not an official Wits exam)"}]];
